package sprint

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	maxSharedPromptPrefixBytes = 512 << 10
	sharedSourceReadBuffer     = 32 << 10
)

type promptContextErrorKind string

const (
	promptContextInvalidPath  promptContextErrorKind = "invalid_path"
	promptContextContainment  promptContextErrorKind = "containment"
	promptContextFileKind     promptContextErrorKind = "file_kind"
	promptContextMissing      promptContextErrorKind = "missing_source"
	promptContextInvalidRange promptContextErrorKind = "invalid_range"
	promptContextChanged      promptContextErrorKind = "changed_during_read"
	promptContextEncoding     promptContextErrorKind = "invalid_encoding"
	promptContextBudget       promptContextErrorKind = "budget_exceeded"
)

type promptContextError struct {
	Kind      promptContextErrorKind
	Path      string
	LineRange string
	Allowed   int
	Observed  int
	Unit      string
	Err       error
}

func (e *promptContextError) Error() string {
	location := e.Path
	if e.LineRange != "" {
		location += ":" + e.LineRange
	}
	if location == "" {
		location = "shared prompt context"
	}
	if e.Kind == promptContextBudget {
		unit := e.Unit
		if unit == "" {
			unit = "bytes"
		}
		return fmt.Sprintf("%s: %s (%d %s observed; %d allowed)", e.Kind, location, e.Observed, unit, e.Allowed)
	}
	if e.Err != nil {
		return fmt.Sprintf("%s: %s: %s", e.Kind, location, safePromptContextCause(e.Err))
	}
	return fmt.Sprintf("%s: %s", e.Kind, location)
}

func (e *promptContextError) Unwrap() error { return e.Err }

func safePromptContextCause(err error) string {
	var pathErr *os.PathError
	if errors.As(err, &pathErr) {
		return pathErr.Op + ": " + pathErr.Err.Error()
	}
	return err.Error()
}

type sharedContextReference struct {
	Name, Path, Lines, Symbol, Rationale string
}

type sharedLineRange struct{ Start, End int }

type sharedSourceSelection struct {
	Path       string
	Lines      string
	Ranges     []sharedLineRange
	References []sharedContextReference
}

var codeContextSymbolRE = regexp.MustCompile(`(?im)^\s*-?\s*\*\*Symbol:\*\*\s*` + "`?" + `([^` + "`" + `\r\n]+)` + "`?" + `\s*$`)

func (s Service) prepareSharedPromptContext(ctx context.Context, sp Sprint, inputs PlanningInputs, persistCache bool) (string, error) {
	// Pre-code-context workspaces retain the compatibility behavior established
	// when the stage was introduced. Once the artifact exists, all covered
	// agent-backed operations use the shared renderer and fail closed.
	if inputs.CodeContext == "" {
		return "", nil
	}
	if findings, err := s.codeContextPrerequisite(sp); err != nil {
		if len(findings) > 0 {
			return "", fmt.Errorf("shared prompt code-context prerequisite failed: %s: %w", formatValidationFindings(findings), err)
		}
		return "", fmt.Errorf("shared prompt code-context prerequisite failed: %w", err)
	}
	target, findings := s.resolveSprintTarget(sp, inputs.ProjectIndex, false)
	if len(findings) > 0 {
		return "", fmt.Errorf("resolve shared prompt implementation target: %s", formatValidationFindings(findings))
	}
	if prefix, cacheErr := loadContextPack(s.root, sp, inputs.Requirements, inputs.CodeContext, target.Path); cacheErr == nil {
		return prefix, nil
	}
	prefix, err := renderSharedPromptContext(ctx, sp, inputs.Requirements, inputs.CodeContext, target.Path)
	if err != nil {
		return "", err
	}
	if persistCache {
		// This is a disposable acceleration layer. Failure to write it must not
		// fail, stale, or rerun the governed stage.
		_ = saveContextPack(s.root, sp, inputs.Requirements, inputs.CodeContext, target.Path, prefix, time.Now().UTC())
	}
	return prefix, nil
}

func (s Service) composeSharedPrompt(ctx context.Context, sp Sprint, inputs PlanningInputs, preview PromptPreview) (PromptPreview, error) {
	return s.composeSharedPromptWithCache(ctx, sp, inputs, preview, false)
}

func (s Service) composeSharedRuntimePrompt(ctx context.Context, sp Sprint, inputs PlanningInputs, preview PromptPreview) (PromptPreview, error) {
	return s.composeSharedPromptWithCache(ctx, sp, inputs, preview, true)
}

func (s Service) composeSharedPromptWithCache(ctx context.Context, sp Sprint, inputs PlanningInputs, preview PromptPreview, persistCache bool) (PromptPreview, error) {
	prefix, err := s.prepareSharedPromptContext(ctx, sp, inputs, persistCache)
	if err != nil {
		return PromptPreview{}, err
	}
	preview.Prompt, err = composeStagePromptChecked(prefix, preview.Prompt)
	if err != nil {
		return PromptPreview{}, err
	}
	explanation := explainComposedPrompt(preview.Prompt)
	preview.Explanation = &explanation
	return preview, nil
}

func composeStagePrompt(prefix, suffix string) string {
	if prefix == "" {
		return suffix
	}
	return prefix + suffix
}

func composeStagePromptChecked(prefix, suffix string) (string, error) {
	return composeStagePrompt(prefix, suffix), nil
}

func renderSharedPromptContext(ctx context.Context, sp Sprint, requirements, codeContext, implementationRoot string) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
	if findings := ValidateCodeContextContent(codeContext); len(findings) > 0 {
		return "", fmt.Errorf("shared prompt code-context artifact failed validation: %s", formatValidationFindings(findings))
	}
	references, err := parseSharedContextReferences(codeContext)
	if err != nil {
		return "", err
	}
	root, err := canonicalImplementationRoot(implementationRoot)
	if err != nil {
		return "", err
	}

	var b strings.Builder
	b.Grow(min(maxSharedPromptPrefixBytes, len(requirements)+len(codeContext)+4096))
	b.WriteString(sharedPromptInstructions)
	fmt.Fprintf(&b, "Project: `%s`\nSprint: `%s`\n", sp.Project, sp.Slug)
	b.WriteString(sharedRequirementsOpen)
	b.WriteString(requirements)
	b.WriteString(sharedRequirementsClose)
	b.WriteString(sharedCodeContextOpen)
	b.WriteString(codeContext)
	b.WriteString(sharedCodeContextClose)
	b.WriteString(sharedSourceEvidenceOpen)
	if err := checkSharedPromptBudget(b.Len(), "", ""); err != nil {
		return "", err
	}
	selections, err := canonicalSharedSelections(references)
	if err != nil {
		return "", err
	}
	for _, selection := range selections {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		available := maxSharedPromptPrefixBytes - b.Len() - len(sharedSourceEvidenceClose) - len(sharedPromptStageBoundary)
		if available < 0 {
			return "", budgetPromptContextError(selection.Path, selection.Lines, maxSharedPromptPrefixBytes, b.Len())
		}
		source, err := readSharedSource(ctx, root, selection.Path, selection.Lines, selection.Ranges, available)
		if err != nil {
			return "", err
		}
		var frame strings.Builder
		fmt.Fprintf(&frame, "\n<<< BEGIN UNTRUSTED TRANSIENT SOURCE EVIDENCE: %s:%s >>>\n", selection.Path, selection.Lines)
		frame.WriteString("Selected entries:")
		for _, ref := range selection.References {
			fmt.Fprintf(&frame, " %s;", ref.Name)
		}
		frame.WriteString("\nSource bytes:\n")
		frame.WriteString(source)
		fmt.Fprintf(&frame, "\n<<< END UNTRUSTED TRANSIENT SOURCE EVIDENCE: %s:%s >>>\n", selection.Path, selection.Lines)
		observed := b.Len() + frame.Len() + len(sharedSourceEvidenceClose) + len(sharedPromptStageBoundary)
		if observed > maxSharedPromptPrefixBytes {
			return "", budgetPromptContextError(selection.Path, selection.Lines, maxSharedPromptPrefixBytes, observed)
		}
		b.WriteString(frame.String())
	}
	b.WriteString(sharedSourceEvidenceClose)
	b.WriteString(sharedPromptStageBoundary)
	if err := checkSharedPromptBudget(b.Len(), "", ""); err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return b.String(), nil
}

func canonicalSharedSelections(refs []sharedContextReference) ([]sharedSourceSelection, error) {
	positions := map[string]int{}
	selections := make([]sharedSourceSelection, 0, len(refs))
	for _, ref := range refs {
		ranges, err := parseSharedLineRanges(ref.Path, ref.Lines)
		if err != nil {
			return nil, err
		}
		position, ok := positions[ref.Path]
		if !ok {
			position = len(selections)
			positions[ref.Path] = position
			selections = append(selections, sharedSourceSelection{Path: ref.Path})
		}
		selections[position].Ranges = append(selections[position].Ranges, ranges...)
		selections[position].References = append(selections[position].References, ref)
	}
	for i := range selections {
		ranges := selections[i].Ranges
		sort.Slice(ranges, func(a, b int) bool {
			if ranges[a].Start != ranges[b].Start {
				return ranges[a].Start < ranges[b].Start
			}
			return ranges[a].End < ranges[b].End
		})
		merged := make([]sharedLineRange, 0, len(ranges))
		for _, current := range ranges {
			if len(merged) == 0 || current.Start > merged[len(merged)-1].End+1 {
				merged = append(merged, current)
				continue
			}
			if current.End > merged[len(merged)-1].End {
				merged[len(merged)-1].End = current.End
			}
		}
		selections[i].Ranges = merged
		selections[i].Lines = formatSharedLineRanges(merged)
	}
	return selections, nil
}

func formatSharedLineRanges(ranges []sharedLineRange) string {
	parts := make([]string, 0, len(ranges))
	for _, selected := range ranges {
		if selected.Start == selected.End {
			parts = append(parts, strconv.Itoa(selected.Start))
		} else {
			parts = append(parts, fmt.Sprintf("%d-%d", selected.Start, selected.End))
		}
	}
	return strings.Join(parts, ",")
}

func parseSharedContextReferences(content string) ([]sharedContextReference, error) {
	entries := codeContextEntries(sectionBody(content, "Selected Source References"))
	refs := make([]sharedContextReference, 0, len(entries))
	for _, entry := range entries {
		path := codeContextPathRE.FindStringSubmatch(entry.body)
		lines := codeContextLinesRE.FindStringSubmatch(entry.body)
		reason := codeContextReasonRE.FindStringSubmatch(entry.body)
		if len(path) != 2 || len(lines) != 2 || len(reason) != 2 {
			return nil, &promptContextError{Kind: promptContextInvalidRange, Path: entry.name, Err: errors.New("validated reference fields could not be parsed")}
		}
		ref := sharedContextReference{
			Name:      strings.TrimSpace(entry.name),
			Path:      strings.Trim(strings.TrimSpace(path[1]), "`"),
			Lines:     strings.Trim(strings.TrimSpace(lines[1]), "`"),
			Rationale: strings.TrimSpace(reason[1]),
		}
		if symbol := codeContextSymbolRE.FindStringSubmatch(entry.body); len(symbol) == 2 {
			ref.Symbol = strings.Trim(strings.TrimSpace(symbol[1]), "`")
		}
		refs = append(refs, ref)
	}
	return refs, nil
}

func parseSharedLineRanges(path, value string) ([]sharedLineRange, error) {
	var ranges []sharedLineRange
	for _, segment := range strings.Split(value, ",") {
		segment = strings.TrimSpace(segment)
		parts := strings.Split(segment, "-")
		start, err := strconv.Atoi(strings.TrimSpace(parts[0]))
		if err != nil || start < 1 || len(parts) > 2 {
			return nil, &promptContextError{Kind: promptContextInvalidRange, Path: path, LineRange: value, Err: errors.New("range must be a positive N or N-M")}
		}
		end := start
		if len(parts) == 2 {
			end, err = strconv.Atoi(strings.TrimSpace(parts[1]))
			if err != nil || end < start {
				return nil, &promptContextError{Kind: promptContextInvalidRange, Path: path, LineRange: value, Err: errors.New("range end precedes its start")}
			}
		}
		ranges = append(ranges, sharedLineRange{Start: start, End: end})
	}
	return ranges, nil
}

func canonicalImplementationRoot(root string) (string, error) {
	if root == "" || !filepath.IsAbs(root) {
		return "", &promptContextError{Kind: promptContextContainment, Err: errors.New("implementation root must be absolute")}
	}
	canonical, err := filepath.EvalSymlinks(filepath.Clean(root))
	if err != nil {
		return "", &promptContextError{Kind: promptContextContainment, Err: fmt.Errorf("resolve implementation root: %w", err)}
	}
	info, err := os.Stat(canonical)
	if err != nil {
		return "", &promptContextError{Kind: promptContextContainment, Err: fmt.Errorf("inspect implementation root: %w", err)}
	}
	if !info.IsDir() {
		return "", &promptContextError{Kind: promptContextFileKind, Err: errors.New("implementation root is not a directory")}
	}
	return canonical, nil
}

func readSharedSource(ctx context.Context, root, rel, lineRange string, ranges []sharedLineRange, budget int) (string, error) {
	if err := validateRepositoryRelativePath(rel); err != nil {
		return "", &promptContextError{Kind: promptContextInvalidPath, Path: rel, LineRange: lineRange, Err: err}
	}
	candidate := filepath.Join(root, filepath.FromSlash(rel))
	if !inside(root, candidate) {
		return "", &promptContextError{Kind: promptContextContainment, Path: rel, LineRange: lineRange, Err: errors.New("path escapes implementation root")}
	}
	current := root
	for _, component := range strings.Split(filepath.ToSlash(rel), "/") {
		current = filepath.Join(current, filepath.FromSlash(component))
		info, err := os.Lstat(current)
		if err != nil {
			kind := promptContextMissing
			if !os.IsNotExist(err) {
				kind = promptContextContainment
			}
			return "", &promptContextError{Kind: kind, Path: rel, LineRange: lineRange, Err: err}
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return "", &promptContextError{Kind: promptContextContainment, Path: rel, LineRange: lineRange, Err: errors.New("symlink components are not allowed")}
		}
	}
	canonical, err := filepath.EvalSymlinks(candidate)
	if err != nil || !inside(root, canonical) {
		if err == nil {
			err = errors.New("canonical path escapes implementation root")
		}
		return "", &promptContextError{Kind: promptContextContainment, Path: rel, LineRange: lineRange, Err: err}
	}
	before, err := os.Stat(candidate)
	if err != nil {
		return "", &promptContextError{Kind: promptContextMissing, Path: rel, LineRange: lineRange, Err: err}
	}
	if !before.Mode().IsRegular() {
		return "", &promptContextError{Kind: promptContextFileKind, Path: rel, LineRange: lineRange, Err: errors.New("selected source is not a regular file")}
	}
	f, err := os.Open(candidate)
	if err != nil {
		return "", &promptContextError{Kind: promptContextMissing, Path: rel, LineRange: lineRange, Err: err}
	}
	defer f.Close()
	handleBefore, err := f.Stat()
	if err != nil || !handleBefore.Mode().IsRegular() || !os.SameFile(before, handleBefore) {
		if err == nil {
			err = errors.New("opened source identity does not match the selected path")
		}
		return "", &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}

	data, totalLines, err := readSharedLineRanges(ctx, f, ranges, budget)
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return "", err
		}
		return "", &promptContextError{Kind: promptContextBudget, Path: rel, LineRange: lineRange, Allowed: budget, Observed: budget + 1, Err: err}
	}
	for _, selected := range ranges {
		if selected.End > totalLines {
			return "", &promptContextError{Kind: promptContextInvalidRange, Path: rel, LineRange: lineRange, Err: fmt.Errorf("range ends at line %d but file has %d lines", selected.End, totalLines)}
		}
	}
	source := string(data)
	if !utf8.ValidString(source) {
		return "", &promptContextError{Kind: promptContextEncoding, Path: rel, LineRange: lineRange, Err: errors.New("selected source is not valid UTF-8")}
	}
	handleAfter, err := f.Stat()
	if err != nil {
		return "", &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}
	if err := verifySharedSourceUnchanged(root, candidate, canonical, rel, lineRange, handleBefore, handleAfter); err != nil {
		return "", err
	}
	return source, nil
}

func verifySharedSourceUnchanged(root, candidate, canonical, rel, lineRange string, handleBefore, handleAfter os.FileInfo) error {
	after, err := os.Stat(candidate)
	if err != nil || !os.SameFile(handleBefore, handleAfter) || !os.SameFile(handleBefore, after) || handleBefore.Size() != handleAfter.Size() || !handleBefore.ModTime().Equal(handleAfter.ModTime()) {
		if err == nil {
			err = errors.New("selected source changed while it was read")
		}
		return &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}
	canonicalAfter, err := filepath.EvalSymlinks(candidate)
	if err != nil || canonicalAfter != canonical || !inside(root, canonicalAfter) {
		if err == nil {
			err = errors.New("selected source canonical location changed while it was read")
		}
		return &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}
	return nil
}

func readSharedLineRange(ctx context.Context, r io.Reader, selected sharedLineRange, budget int) ([]byte, int, error) {
	return readSharedLineRanges(ctx, r, []sharedLineRange{selected}, budget)
}

func readSharedLineRanges(ctx context.Context, r io.Reader, selected []sharedLineRange, budget int) ([]byte, int, error) {
	reader := bufio.NewReaderSize(r, sharedSourceReadBuffer)
	line := 1
	total := 0
	var out []byte
	rangeIndex := 0
	for {
		if err := ctx.Err(); err != nil {
			return nil, 0, err
		}
		fragment, err := reader.ReadSlice('\n')
		if len(fragment) > 0 {
			total = line
			for rangeIndex < len(selected) && line > selected[rangeIndex].End {
				rangeIndex++
			}
			included := rangeIndex < len(selected) && line >= selected[rangeIndex].Start && line <= selected[rangeIndex].End
			if included {
				if len(fragment) > budget-len(out) {
					return nil, 0, errors.New("selected source exceeds remaining shared prompt budget")
				}
				out = append(out, fragment...)
			}
			if fragment[len(fragment)-1] == '\n' {
				line++
			}
		}
		switch err {
		case nil:
			continue
		case bufio.ErrBufferFull:
			continue
		case io.EOF:
			return out, total, nil
		default:
			return nil, 0, err
		}
	}
}

func checkSharedPromptBudget(observed int, path, lineRange string) error {
	if observed <= maxSharedPromptPrefixBytes {
		return nil
	}
	return budgetPromptContextError(path, lineRange, maxSharedPromptPrefixBytes, observed)
}

func budgetPromptContextError(path, lineRange string, allowed, observed int) error {
	return &promptContextError{Kind: promptContextBudget, Path: path, LineRange: lineRange, Allowed: allowed, Observed: observed}
}

package sprint

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/platform/gitpublish"
	"github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

type Runtime interface {
	StartRun(context.Context, runtime.Request) (runtime.Result, error)
}

type sessionDeleter interface {
	DeleteSession(context.Context, string) error
}

type runtimeStoreDeleter interface {
	DeleteRuntimeStore(context.Context, string) error
}

func (s Service) deleteCompletedSession(ctx context.Context, sessionID string) error {
	if strings.TrimSpace(sessionID) == "" {
		return nil
	}
	deleter, ok := s.runtime.(sessionDeleter)
	if !ok {
		return nil
	}
	return deleter.DeleteSession(ctx, sessionID)
}

func (s Service) deleteCompletedSessions(ctx context.Context, result runtime.Result) error {
	if result.RuntimeStorePath != "" {
		if deleter, ok := s.runtime.(runtimeStoreDeleter); ok {
			return deleter.DeleteRuntimeStore(ctx, result.RuntimeStorePath)
		}
	}
	ids := append([]string(nil), result.SessionIDs...)
	ids = append(ids, result.SessionID)
	seen := map[string]bool{}
	for _, id := range ids {
		if strings.TrimSpace(id) == "" || seen[id] {
			continue
		}
		seen[id] = true
		if err := s.deleteCompletedSession(ctx, id); err != nil {
			return err
		}
	}
	return nil
}

type FlowRequest struct {
	To              PlanningStage
	DryRun          bool
	ModelOverride   string
	VariantOverride string
	// StageOverrides optionally sets a per-stage runtime model and/or variant
	// for this flow invocation. Stages without an entry keep their configured
	// defaults unchanged.
	StageOverrides map[PlanningStage]StageRuntime
	Review         ReviewRequest
	Smoke          SmokeRequest
	Progress       func(FlowProgress)
}

type FlowProgress struct {
	Stage   PlanningStage
	State   string
	Message string
}

type FlowResult struct {
	Project      string
	Sprint       string
	To           PlanningStage
	DryRun       bool
	Message      string
	Runtime      runtime.Result
	Stages       []StageState
	Findings     []ValidationFinding
	Publications []gitpublish.Result
}

// Flow owns the ordered sprint state machine. Surfaces map requests and render
// this result; they do not schedule stages or duplicate verification policy.
func (s Service) Flow(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	stages, err := flowStages(req.To)
	if err != nil {
		return FlowResult{}, err
	}
	if req.DryRun {
		if req.To == StageReview || req.To == StageSmoke {
			verified, verifyErr := s.Verify(ctx, projectRef, sprintRef, VerifyRequest{To: req.To, DryRun: true, Review: req.Review, Smoke: req.Smoke, Progress: req.Progress})
			message := "verification dry run"
			if verified.ReviewResult != nil {
				message = firstNonEmptyString(verified.ReviewResult.Prompt, verified.ReviewResult.Message, message)
			}
			return FlowResult{Project: verified.Project, Sprint: verified.Sprint, To: req.To, DryRun: true, Message: message}, verifyErr
		}
		stages = []PlanningStage{req.To}
	} else {
		// A non-dry flow is the materialization entrypoint for a roadmap sprint.
		// Create its safe skeleton before acquiring the sprint-scoped mutation
		// lease; lease resolution deliberately accepts existing sprints only.
		sp, _, _, resolveErr := s.resolveSprintForRequirements(projectRef, sprintRef, true)
		if resolveErr != nil {
			return FlowResult{}, resolveErr
		}
		sprintRef = sp.Slug
		var release func()
		ctx, release, err = s.acquireMutationContext(ctx, projectRef, sprintRef)
		if err != nil {
			return FlowResult{}, err
		}
		defer release()
	}
	var result FlowResult
	for _, stage := range stages {
		emitFlow(req.Progress, FlowProgress{Stage: stage, State: "checking", Message: "checking prerequisites and existing artifact"})
		stageReq := FlowRequest{To: stage, DryRun: req.DryRun, ModelOverride: req.ModelOverride, VariantOverride: req.VariantOverride}
		if !req.DryRun {
			valid, validateErr := s.flowStageAlreadyValid(projectRef, sprintRef, stage)
			if validateErr != nil {
				return FlowResult{}, validateErr
			}
			if valid {
				if stage == StageCodeContext {
					sp, inputs, _, resolveErr := s.resolveSprintInputs(projectRef, sprintRef)
					if resolveErr != nil {
						return FlowResult{}, resolveErr
					}
					if _, findings := s.resolveSprintTarget(sp, inputs.ProjectIndex, true); len(findings) > 0 {
						return FlowResult{Project: sp.Project, Sprint: sp.Slug, To: stage, Findings: findings}, fmt.Errorf("code-context sprint workspace creation failed")
					}
				}
				if stage != StageExecute {
					if sp, _, _, resolveErr := s.resolveSprintInputs(projectRef, sprintRef); resolveErr == nil {
						_ = clearPlanningStageSession(sp, stage)
					}
				}
				result = FlowResult{Project: projectRef, Sprint: sprintRef, To: stage, Message: string(stage) + " already complete"}
				if stage != StageExecute {
					publications, publishErr := s.publishPlanningStage(ctx, projectRef, sprintRef, stage)
					result.Publications = append(result.Publications, publications...)
					if publishErr != nil {
						emitFlow(req.Progress, FlowProgress{Stage: stage, State: "publish-failed", Message: publishErr.Error()})
						return result, publishErr
					}
				}
				emitFlow(req.Progress, FlowProgress{Stage: stage, State: "skipped", Message: "already complete"})
				continue
			}
			emitFlow(req.Progress, FlowProgress{Stage: stage, State: "running", Message: "starting runtime-backed stage"})
		}
		var stageErr error
		result, stageErr = s.withStageOverrides(req.StageOverrides).runFlowStage(ctx, projectRef, sprintRef, stageReq)
		if stageErr != nil {
			emitFlow(req.Progress, FlowProgress{Stage: stage, State: "failed", Message: "stage failed; inspect validation findings and durable state"})
			return result, stageErr
		}
		if !req.DryRun && stage != StageExecute {
			emitFlow(req.Progress, FlowProgress{Stage: stage, State: "publishing", Message: "committing completed stage changes"})
			publications, publishErr := s.publishPlanningStage(ctx, projectRef, sprintRef, stage)
			result.Publications = append(result.Publications, publications...)
			if publishErr != nil {
				emitFlow(req.Progress, FlowProgress{Stage: stage, State: "publish-failed", Message: publishErr.Error()})
				return result, publishErr
			}
		}
		emitFlow(req.Progress, FlowProgress{Stage: stage, State: "complete", Message: firstNonEmptyString(result.Message, "stage complete")})
	}
	if req.To == StageReview || req.To == StageSmoke {
		verified, verifyErr := s.Verify(ctx, projectRef, sprintRef, VerifyRequest{To: req.To, Review: req.Review, Smoke: req.Smoke, Progress: req.Progress})
		message := fmt.Sprintf("verification assessment=%s next=%s", verified.Verification.Assessment, verified.Verification.NextAction)
		return FlowResult{Project: verified.Project, Sprint: verified.Sprint, To: req.To, Message: message}, verifyErr
	}
	result.To = req.To
	return result, nil
}

// FlowStage runs exactly one planning stage. It preserves the stage's normal
// prerequisite validation while deliberately not scheduling earlier stages.
func (s Service) FlowStage(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	if err := validatePlanningStageTarget(req.To); err != nil {
		return FlowResult{}, err
	}
	if !req.DryRun {
		sp, _, _, resolveErr := s.resolveSprintForRequirements(projectRef, sprintRef, true)
		if resolveErr != nil {
			return FlowResult{}, resolveErr
		}
		sprintRef = sp.Slug
		var release func()
		var err error
		ctx, release, err = s.acquireMutationContext(ctx, projectRef, sprintRef)
		if err != nil {
			return FlowResult{}, err
		}
		defer release()
	}
	emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "running", Message: "running selected stage only"})
	result, err := s.withStageOverrides(req.StageOverrides).runFlowStage(ctx, projectRef, sprintRef, req)
	if err != nil {
		emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "failed", Message: "stage failed; inspect validation findings and durable state"})
		return result, err
	}
	if !req.DryRun {
		emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "publishing", Message: "committing completed stage changes"})
		publications, publishErr := s.publishPlanningStage(ctx, projectRef, sprintRef, req.To)
		result.Publications = append(result.Publications, publications...)
		if publishErr != nil {
			emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "publish-failed", Message: publishErr.Error()})
			return result, publishErr
		}
	}
	emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "complete", Message: firstNonEmptyString(result.Message, "stage complete")})
	return result, nil
}

func (s Service) runFlowStage(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	switch req.To {
	case StageRequirements:
		return s.FlowRequirements(ctx, projectRef, sprintRef, req)
	case StageCodeContext:
		return s.FlowCodeContext(ctx, projectRef, sprintRef, req)
	case StageSprintIndex:
		return s.FlowSprintIndex(ctx, projectRef, sprintRef, req)
	case StageTechnicalHandbook:
		return s.FlowTechnicalHandbook(ctx, projectRef, sprintRef, req)
	case StageAreaReasoning, StageReasoning:
		return s.FlowReasoning(ctx, projectRef, sprintRef, req)
	case StagePlan:
		return s.FlowPlan(ctx, projectRef, sprintRef, req)
	case StageExecute:
		execute, err := s.Execute(ctx, projectRef, sprintRef, ExecuteRequest{DryRun: req.DryRun, Resume: true})
		return FlowResult{Project: execute.Project, Sprint: execute.Sprint, To: StageExecute, DryRun: execute.DryRun, Message: firstNonEmptyString(execute.Prompt, execute.Message), Findings: execute.Findings}, err
	default:
		return FlowResult{}, fmt.Errorf("unsupported flow stage %q", req.To)
	}
}

func validatePlanningStageTarget(stage PlanningStage) error {
	switch stage {
	case StageRequirements, StageCodeContext, StageSprintIndex, StageTechnicalHandbook, StageAreaReasoning, StageReasoning, StagePlan:
		return nil
	default:
		return fmt.Errorf("unsupported single planning stage %q", stage)
	}
}

func flowStages(target PlanningStage) ([]PlanningStage, error) {
	if err := validateFlowTarget(target); err != nil {
		return nil, err
	}
	ordered := append(PlanningStages(), StageExecute)
	end := 0
	switch target {
	case StageRequirements:
		end = 1
	case StageCodeContext:
		end = 2
	case StageSprintIndex:
		end = 3
	case StageTechnicalHandbook:
		end = 4
	case StageAreaReasoning:
		end = 5
	case StageReasoning:
		end = 6
	case StagePlan:
		end = 7
	case StageExecute, StageReview, StageSmoke:
		end = 8
	}
	return append([]PlanningStage(nil), ordered[:end]...), nil
}

func (s Service) flowStageAlreadyValid(projectRef, sprintRef string, stage PlanningStage) (bool, error) {
	var result ValidationResult
	var err error
	switch stage {
	case StageRequirements:
		result, err = s.ValidateRequirements(projectRef, sprintRef)
	case StageCodeContext:
		sp, _, _, resolveErr := s.resolveSprintInputs(projectRef, sprintRef)
		if resolveErr != nil {
			return false, resolveErr
		}
		_, prerequisiteErr := s.codeContextPrerequisite(sp)
		return prerequisiteErr == nil, nil
	case StageSprintIndex:
		result, err = s.ValidateSprintIndex(projectRef, sprintRef)
	case StageTechnicalHandbook:
		result, err = s.ValidateTechnicalHandbook(projectRef, sprintRef)
	case StageAreaReasoning:
		result, err = s.ValidateAreaReasoning(projectRef, sprintRef)
	case StageReasoning:
		result, err = s.ValidateReasoning(projectRef, sprintRef)
	case StagePlan:
		result, err = s.ValidatePlan(projectRef, sprintRef)
	case StageExecute:
		return s.ExecuteComplete(projectRef, sprintRef)
	default:
		return false, fmt.Errorf("unsupported flow stage %q", stage)
	}
	if err != nil {
		return false, nil
	}
	return result.Valid(), nil
}

func emitFlow(progress func(FlowProgress), event FlowProgress) {
	if progress != nil {
		progress(event)
	}
}

func flowRequirementsSuccessStages(sp Sprint, now time.Time) []StageState {
	stages := emptyPlanningStageStates(sp)
	setFlowStage(stages, StageRequirements, StatusComplete, &now, "")
	setFlowStage(stages, StageCodeContext, StatusReady, nil, "")
	return stages
}

func flowCodeContextSuccessStages(sp Sprint, now time.Time) []StageState {
	stages := flowRequirementsSuccessStages(sp, now)
	setFlowStage(stages, StageCodeContext, StatusComplete, &now, "")
	setFlowStage(stages, StageSprintIndex, StatusReady, nil, "")
	return stages
}

func flowSprintIndexSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowCodeContextSuccessStages(sp, now)
	setFlowStage(stages, StageSprintIndex, StatusComplete, &now, "")
	setFlowStage(stages, StageTechnicalHandbook, StatusReady, nil, "")
	if noTemplates {
		setFlowStage(stages, StageAreaReasoning, StatusSkipped, nil, "")
		setFlowStage(stages, StageReasoning, StatusReady, nil, "")
	}
	return stages
}

func flowTechnicalHandbookSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowSprintIndexSuccessStages(sp, false, now)
	setFlowStage(stages, StageTechnicalHandbook, StatusComplete, &now, "")
	setFlowStage(stages, StageAreaReasoning, StatusReady, nil, "")
	if noTemplates {
		setFlowStage(stages, StageAreaReasoning, StatusSkipped, nil, "")
		setFlowStage(stages, StageReasoning, StatusReady, nil, "")
	}
	return stages
}

func flowAreaReasoningSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowTechnicalHandbookSuccessStages(sp, noTemplates, now)
	if noTemplates {
		setFlowStage(stages, StageAreaReasoning, StatusSkipped, &now, "")
		setFlowStage(stages, StageReasoning, StatusReady, nil, "")
		return stages
	}
	setFlowStage(stages, StageAreaReasoning, StatusComplete, &now, "")
	setFlowStage(stages, StageReasoning, StatusReady, nil, "")
	return stages
}

func flowReasoningSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowAreaReasoningSuccessStages(sp, noTemplates, now)
	setFlowStage(stages, StageReasoning, StatusComplete, &now, "")
	setFlowStage(stages, StagePlan, StatusReady, nil, "")
	return stages
}

func flowPlanSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowReasoningSuccessStages(sp, noTemplates, now)
	setFlowStage(stages, StagePlan, StatusComplete, &now, "")
	return stages
}

func flowFailedStages(sp Sprint, target PlanningStage, err error, now time.Time) []StageState {
	msg := safeError(err)
	stages := emptyPlanningStageStates(sp)
	for _, stage := range PlanningStages() {
		if stage == target {
			setFlowStage(stages, stage, StatusFailed, &now, msg)
			break
		}
		setFlowStage(stages, stage, StatusComplete, nil, "")
	}
	return stages
}

func emptyPlanningStageStates(sp Sprint) []StageState {
	stages := make([]StageState, 0, len(PlanningStages()))
	for _, stage := range PlanningStages() {
		stages = append(stages, StageState{Stage: stage, Status: StatusMissing, Path: ArtifactRelPath(sp, stage)})
	}
	return stages
}

func setFlowStage(stages []StageState, target PlanningStage, status StageStatus, at *time.Time, detail string) {
	for i := range stages {
		if stages[i].Stage == target {
			stages[i].Status, stages[i].LastRunAt, stages[i].Error = status, at, detail
			return
		}
	}
}

func safeError(err error) string {
	if err == nil {
		return ""
	}
	msg := config.RedactValue("sprint.stage_error", err.Error())
	msg = strings.ReplaceAll(msg, "\n", " ")
	msg = strings.ReplaceAll(msg, "\r", " ")
	msg = strings.ReplaceAll(msg, "\x00", "")
	if len(msg) > 180 {
		msg = msg[:180]
	}
	return msg
}

func validateFlowTarget(stage PlanningStage) error {
	if stage != StageRequirements && stage != StageCodeContext && stage != StageSprintIndex && stage != StageTechnicalHandbook && stage != StageAreaReasoning && stage != StageReasoning && stage != StagePlan && stage != StageExecute && stage != StageReview && stage != StageSmoke {
		return fmt.Errorf("unsupported sprint flow target %q; supports requirements, code-context, sprint-index, technical-handbook, area-reasoning, reasoning, plan, execute, review, and smoke", stage)
	}
	return nil
}

