package sprint

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type EvidenceEntry struct {
	Name    string
	Path    string
	RelPath string
}

type HandbookManifest struct {
	ProjectSlug      string
	SprintSlug       string
	SprintRoot       string
	RequirementsPath string
	ProjectIndexPath string
	SprintIndexPath  string
	OutputPath       string
	Evidence         []EvidenceEntry
}

func BuildHandbookManifest(root string, sp Sprint, inputs PlanningInputs, catalog project.ProjectIndex) (HandbookManifest, []ValidationFinding) {
	index, findings := ValidateSprintIndexContent(inputs.SprintIndex, catalog)
	manifest := HandbookManifest{
		ProjectSlug:      sp.Project,
		SprintSlug:       sp.Slug,
		SprintRoot:       filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug)),
		RequirementsPath: ArtifactRelPath(sp, StageRequirements),
		ProjectIndexPath: filepath.ToSlash(filepath.Join("projects", sp.Project, "project-index.md")),
		SprintIndexPath:  ArtifactRelPath(sp, StageSprintIndex),
		OutputPath:       ArtifactRelPath(sp, StageTechnicalHandbook),
	}
	seen := map[string]bool{}
	for _, selected := range index.EvidenceReports {
		key := strings.ToLower(selected.Name + "\x00" + selected.Path)
		if seen[key] {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "duplicate selected evidence", "same evidence report appears more than once", "Remove the duplicate selected evidence row."))
			continue
		}
		seen[key] = true
		entry, ok := catalogEvidence(catalog, selected)
		if !ok {
			continue
		}
		rel := normalizeWorkspacePath(entry.Path)
		if filepath.IsAbs(rel) || strings.HasPrefix(filepath.ToSlash(filepath.Clean(filepath.FromSlash(rel))), "../") {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "unsafe evidence path", "path escapes the workspace", "Use a workspace-relative catalog path."))
			continue
		}
		full, err := workspace.ResolveInside(root, rel)
		if err != nil {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "unsafe evidence path", err.Error(), "Use a workspace-relative catalog path."))
			continue
		}
		info, err := os.Stat(full)
		if err != nil {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "unreadable selected evidence", err.Error(), "Ensure the selected report exists and is readable."))
			continue
		}
		if info.IsDir() || info.Size() == 0 {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "invalid selected evidence file", "path is empty or a directory", "Select a non-empty Markdown evidence report."))
			continue
		}
		manifest.Evidence = append(manifest.Evidence, EvidenceEntry{Name: selected.Name, Path: selected.Path, RelPath: rel})
	}
	sort.SliceStable(manifest.Evidence, func(i, j int) bool {
		if manifest.Evidence[i].Name != manifest.Evidence[j].Name {
			return manifest.Evidence[i].Name < manifest.Evidence[j].Name
		}
		return manifest.Evidence[i].Path < manifest.Evidence[j].Path
	})
	sortSprintFindings(findings)
	return manifest, findings
}

func ValidateTechnicalHandbookContent(content string, manifest HandbookManifest) []ValidationFinding {
	var findings []ValidationFinding
	if strings.TrimSpace(content) == "" {
		return []ValidationFinding{finding("technical-handbook.md", "", "", "empty technical handbook", "file has no content", "Generate or write the required handbook sections.")}
	}
	if containsPlaceholder(content) {
		findings = append(findings, finding("technical-handbook.md", "", "", "placeholder content", "file still contains placeholder markers", "Replace placeholders with concrete handbook content."))
	}
	sections := markdownSections(content)
	required := []string{"Selected Studies And Reports", "Relevant Patterns", "Trade-Offs", "Anti-Patterns And Warnings", "Open Questions For Reasoning", "Evidence Pointers"}
	for _, section := range required {
		if strings.TrimSpace(sections[section]) == "" {
			findings = append(findings, finding(section, "", "", "missing required section", "section was not found or has no content", "Add evidence-backed handbook content for this section."))
		}
	}
	traceText := sections["Selected Studies And Reports"] + "\n" + sections["Evidence Pointers"]
	for _, evidence := range manifest.Evidence {
		if !strings.Contains(traceText, evidence.Name) && !strings.Contains(traceText, evidence.Path) && !strings.Contains(traceText, evidence.RelPath) {
			findings = append(findings, finding("Evidence Pointers", evidence.Name, evidence.Path, "missing selected evidence trace", "selected evidence is not cited in handbook evidence sections", "Cite each selected report name or selected report path."))
		}
	}
	allowed := map[string]bool{}
	for _, evidence := range manifest.Evidence {
		allowed[strings.ToLower(evidence.Name)] = true
		allowed[strings.ToLower(evidence.Path)] = true
		allowed[strings.ToLower(evidence.RelPath)] = true
	}
	for _, path := range markdownPaths(content) {
		lp := strings.ToLower(path)
		normalized := strings.ToLower(normalizeWorkspacePath(path))
		if strings.Contains(lp, "/reports/final/") && !allowed[lp] && !allowed[normalized] {
			findings = append(findings, finding("Evidence Pointers", "", path, "unselected evidence reference", "handbook cites a report that is not selected by sprint-index.md", "Use only selected evidence reports."))
		}
	}
	sortSprintFindings(findings)
	return findings
}

func catalogEvidence(catalog project.ProjectIndex, selected SelectedItem) (project.CatalogEntry, bool) {
	for _, entry := range catalog.Entries {
		if entry.Section == project.SectionAvailableEvidenceReports && strings.EqualFold(entry.Name, selected.Name) && entry.Path == selected.Path {
			return entry, true
		}
	}
	return project.CatalogEntry{}, false
}

func normalizeWorkspacePath(path string) string {
	path = strings.Trim(path, "`")
	path = filepath.ToSlash(path)
	if strings.HasPrefix(path, "ultra/") {
		path = "." + path
	}
	return strings.TrimPrefix(path, ".ultra/")
}

func markdownSections(content string) map[string]string {
	sections := map[string]string{}
	current := ""
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "## ") {
			current = strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
			sections[current] = ""
			continue
		}
		if current != "" {
			sections[current] += line + "\n"
		}
	}
	return sections
}

var mdPathPattern = regexp.MustCompile(`(?:\.ultra/)?[A-Za-z0-9._/-]+/reports/final/[A-Za-z0-9._/-]+\.md`)

func markdownPaths(content string) []string {
	matches := mdPathPattern.FindAllString(content, -1)
	out := make([]string, 0, len(matches))
	seen := map[string]bool{}
	for _, match := range matches {
		match = strings.Trim(match, "`.,);")
		if strings.HasPrefix(match, "ultra/") {
			match = "." + match
		}
		if !seen[match] {
			seen[match] = true
			out = append(out, match)
		}
	}
	sort.Strings(out)
	return out
}

func formatManifest(manifest HandbookManifest) string {
	var b strings.Builder
	fmt.Fprintf(&b, "- Project: %s\n", manifest.ProjectSlug)
	fmt.Fprintf(&b, "- Sprint: %s\n", manifest.SprintSlug)
	fmt.Fprintf(&b, "- Sprint root: %s\n", manifest.SprintRoot)
	fmt.Fprintf(&b, "- Requirements: %s\n", manifest.RequirementsPath)
	fmt.Fprintf(&b, "- Project index: %s\n", manifest.ProjectIndexPath)
	fmt.Fprintf(&b, "- Sprint index: %s\n", manifest.SprintIndexPath)
	fmt.Fprintf(&b, "- Output: %s\n", manifest.OutputPath)
	fmt.Fprintln(&b, "- Selected evidence:")
	for _, evidence := range manifest.Evidence {
		fmt.Fprintf(&b, "  - %s: %s\n", evidence.Name, evidence.Path)
	}
	return b.String()
}

package sprint

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type ReasoningTemplateEntry struct {
	Name       string
	Template   string
	OutputPath string
	Why        string
}

type ReasoningManifest struct {
	ProjectSlug        string
	SprintSlug         string
	SprintRoot         string
	RequirementsPath   string
	SprintIndexPath    string
	HandbookPath       string
	FinalOutputPath    string
	Contracts          []SelectedItem
	EvidenceReports    []SelectedItem
	ReviewProtocols    []SelectedItem
	ExcludedContexts   []SelectedItem
	ReasoningTemplates []ReasoningTemplateEntry
}

func BuildReasoningManifest(root string, sp Sprint, inputs PlanningInputs, catalog project.ProjectIndex) (ReasoningManifest, []ValidationFinding) {
	index, findings := ValidateSprintIndexContent(inputs.SprintIndex, catalog)
	manifest := ReasoningManifest{
		ProjectSlug:      sp.Project,
		SprintSlug:       sp.Slug,
		SprintRoot:       filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug)),
		RequirementsPath: ArtifactRelPath(sp, StageRequirements),
		SprintIndexPath:  ArtifactRelPath(sp, StageSprintIndex),
		HandbookPath:     ArtifactRelPath(sp, StageTechnicalHandbook),
		FinalOutputPath:  ArtifactRelPath(sp, StageReasoning),
		Contracts:        append([]SelectedItem(nil), index.Contracts...),
		EvidenceReports:  append([]SelectedItem(nil), index.EvidenceReports...),
		ReviewProtocols:  append([]SelectedItem(nil), index.ReviewProtocols...),
		ExcludedContexts: append([]SelectedItem(nil), index.ExcludedContexts...),
	}
	for _, selected := range index.ReasoningTemplates {
		catalogEntry, ok := catalogReasoningTemplate(catalog, selected.Name)
		if !ok {
			continue
		}
		templateRel := normalizeWorkspacePath(catalogEntry.Path)
		if !safeWorkspaceRel(templateRel) {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "unsafe template path", "template path escapes the workspace", "Use a workspace-relative catalog path."))
			continue
		}
		full, err := workspace.ResolveInside(root, templateRel)
		if err != nil {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "unsafe template path", err.Error(), "Use a workspace-relative catalog path."))
			continue
		}
		info, err := os.Stat(full)
		if err != nil {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "unreadable selected template", err.Error(), "Ensure the selected reasoning template exists and is readable."))
			continue
		}
		if info.IsDir() || info.Size() == 0 {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "invalid selected template file", "path is empty or a directory", "Select a non-empty Markdown reasoning template."))
			continue
		}
		if !reasoningOutputInsideSprint(sp, selected.Path) {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, selected.Path, "unsafe output path", "output path must be under the selected sprint reasoning directory", "Use projects/<project>/sprints/<sprint>/reasoning/<area>.md."))
			continue
		}
		manifest.ReasoningTemplates = append(manifest.ReasoningTemplates, ReasoningTemplateEntry{
			Name:       selected.Name,
			Template:   catalogEntry.Path,
			OutputPath: selected.Path,
			Why:        selected.Why,
		})
	}
	sort.SliceStable(manifest.ReasoningTemplates, func(i, j int) bool {
		if manifest.ReasoningTemplates[i].Name != manifest.ReasoningTemplates[j].Name {
			return manifest.ReasoningTemplates[i].Name < manifest.ReasoningTemplates[j].Name
		}
		return manifest.ReasoningTemplates[i].OutputPath < manifest.ReasoningTemplates[j].OutputPath
	})
	sortSprintFindings(findings)
	return manifest, findings
}

func ValidateAreaReasoningContent(content string, entry ReasoningTemplateEntry, manifest ReasoningManifest) []ValidationFinding {
	var findings []ValidationFinding
	if strings.TrimSpace(content) == "" {
		return []ValidationFinding{finding("area-reasoning", entry.Name, entry.OutputPath, "empty area reasoning", "file has no content", "Generate or write the required area reasoning sections.")}
	}
	if containsPlaceholder(content) {
		findings = append(findings, finding("area-reasoning", entry.Name, entry.OutputPath, "placeholder content", "file still contains placeholder markers", "Replace placeholders with concrete reasoning content."))
	}
	sections := markdownSections(content)
	for _, section := range []string{"Area Decisions", "Trade-Offs", "Evidence", "Risks"} {
		if strings.TrimSpace(sections[section]) == "" {
			findings = append(findings, finding(section, entry.Name, entry.OutputPath, "missing required section", "section was not found or has no content", "Add the required area reasoning section."))
		}
	}
	if !strings.Contains(content, entry.Name) && !strings.Contains(content, entry.Template) {
		findings = append(findings, finding("Evidence", entry.Name, entry.OutputPath, "missing selected template trace", "area reasoning does not name the selected template", "Reference the selected area/template being reasoned through."))
	}
	findings = append(findings, validateSelectedContextReferences(content, manifest)...)
	sortSprintFindings(findings)
	return findings
}

func ValidateFinalReasoningContent(content string, manifest ReasoningManifest) []ValidationFinding {
	var findings []ValidationFinding
	if strings.TrimSpace(content) == "" {
		return []ValidationFinding{finding("reasoning.md", "", manifest.FinalOutputPath, "empty final reasoning", "file has no content", "Generate or write the required final reasoning sections.")}
	}
	if containsPlaceholder(content) {
		findings = append(findings, finding("reasoning.md", "", manifest.FinalOutputPath, "placeholder content", "file still contains placeholder markers", "Replace placeholders with concrete reasoning content."))
	}
	sections := markdownSections(content)
	for _, section := range []string{"Decisions", "Expected Evidence", "Assumptions And Risks", "Implementation Constraints"} {
		if strings.TrimSpace(sections[section]) == "" {
			findings = append(findings, finding(section, "", manifest.FinalOutputPath, "missing required section", "section was not found or has no content", "Add the required final reasoning section."))
		}
	}
	for _, entry := range manifest.ReasoningTemplates {
		if !strings.Contains(content, entry.OutputPath) && !strings.Contains(content, entry.Name) {
			findings = append(findings, finding("Area-Specific Reasoning Inputs", entry.Name, entry.OutputPath, "missing selected area reference", "final reasoning does not reference a selected area reasoning artifact", "Reference each selected area reasoning output before completing final reasoning."))
		}
	}
	findings = append(findings, validateSelectedContextReferences(content, manifest)...)
	sortSprintFindings(findings)
	return findings
}

func validateSelectedContextReferences(content string, manifest ReasoningManifest) []ValidationFinding {
	allowed := map[string]bool{}
	for _, item := range manifest.Contracts {
		allowed[strings.ToLower(item.Name)] = true
		allowed[strings.ToLower(item.Path)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(item.Path))] = true
	}
	for _, item := range manifest.EvidenceReports {
		allowed[strings.ToLower(item.Name)] = true
		allowed[strings.ToLower(item.Path)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(item.Path))] = true
	}
	for _, item := range manifest.ReviewProtocols {
		allowed[strings.ToLower(item.Name)] = true
		allowed[strings.ToLower(item.Path)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(item.Path))] = true
	}
	for _, entry := range manifest.ReasoningTemplates {
		allowed[strings.ToLower(entry.Name)] = true
		allowed[strings.ToLower(entry.Template)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(entry.Template))] = true
		allowed[strings.ToLower(entry.OutputPath)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(entry.OutputPath))] = true
	}
	allowed[strings.ToLower(manifest.RequirementsPath)] = true
	allowed[strings.ToLower(manifest.SprintIndexPath)] = true
	allowed[strings.ToLower(manifest.HandbookPath)] = true
	allowed[strings.ToLower(manifest.FinalOutputPath)] = true
	var findings []ValidationFinding
	for _, path := range selectedContextPaths(content) {
		lp := strings.ToLower(path)
		normalized := strings.ToLower(normalizeWorkspacePath(path))
		if allowed[lp] || allowed[normalized] {
			continue
		}
		findings = append(findings, finding("Selected Context", "", path, "unselected context reference", "reasoning cites a path not selected for this sprint", "Use only selected sprint-index context, handbook evidence, and selected area reasoning paths."))
	}
	return findings
}

func selectedContextPaths(content string) []string {
	matches := mdPathPattern.FindAllString(content, -1)
	for _, needle := range []string{".ultra/system/contracts/", ".ultra/system/protocols/", ".ultra/system/reasoning/"} {
		start := 0
		for {
			idx := strings.Index(content[start:], needle)
			if idx < 0 {
				break
			}
			idx += start
			end := idx
			for end < len(content) && !strings.ContainsRune(" \t\r\n`|,);", rune(content[end])) {
				end++
			}
			matches = append(matches, strings.Trim(content[idx:end], "`.,);"))
			start = end
		}
	}
	seen := map[string]bool{}
	var out []string
	for _, match := range matches {
		if match == "" || seen[match] {
			continue
		}
		seen[match] = true
		out = append(out, match)
	}
	sort.Strings(out)
	return out
}

func catalogReasoningTemplate(catalog project.ProjectIndex, name string) (project.CatalogEntry, bool) {
	for _, entry := range catalog.Entries {
		if entry.Section == project.SectionAvailableReasoningTemplate && strings.EqualFold(entry.Name, name) {
			return entry, true
		}
	}
	return project.CatalogEntry{}, false
}

func reasoningOutputInsideSprint(sp Sprint, output string) bool {
	if !safeWorkspaceRel(output) {
		return false
	}
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(normalizeWorkspacePath(output))))
	prefix := filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug, "reasoning")) + "/"
	return strings.HasPrefix(clean, prefix) && strings.ToLower(filepath.Ext(clean)) == ".md"
}

func safeWorkspaceRel(path string) bool {
	if path == "" || filepath.IsAbs(path) || strings.Contains(path, "\x00") {
		return false
	}
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(path)))
	return clean != "." && clean != ".." && !strings.HasPrefix(clean, "../")
}

func formatReasoningManifest(manifest ReasoningManifest) string {
	var b strings.Builder
	fmt.Fprintf(&b, "- Project: %s\n", manifest.ProjectSlug)
	fmt.Fprintf(&b, "- Sprint: %s\n", manifest.SprintSlug)
	fmt.Fprintf(&b, "- Sprint root: %s\n", manifest.SprintRoot)
	fmt.Fprintf(&b, "- Requirements: %s\n", manifest.RequirementsPath)
	fmt.Fprintf(&b, "- Sprint index: %s\n", manifest.SprintIndexPath)
	fmt.Fprintf(&b, "- Technical handbook: %s\n", manifest.HandbookPath)
	fmt.Fprintf(&b, "- Final reasoning output: %s\n", manifest.FinalOutputPath)
	fmt.Fprintln(&b, "- Selected contracts:")
	for _, item := range manifest.Contracts {
		fmt.Fprintf(&b, "  - %s\n", item.Name)
	}
	fmt.Fprintln(&b, "- Selected evidence:")
	for _, item := range manifest.EvidenceReports {
		fmt.Fprintf(&b, "  - %s: %s\n", item.Name, item.Path)
	}
	fmt.Fprintln(&b, "- Selected reasoning templates:")
	if len(manifest.ReasoningTemplates) == 0 {
		fmt.Fprintln(&b, "  - none")
	}
	for _, entry := range manifest.ReasoningTemplates {
		fmt.Fprintf(&b, "  - %s: template=%s output=%s\n", entry.Name, entry.Template, entry.OutputPath)
	}
	fmt.Fprintln(&b, "- Required review protocols:")
	for _, item := range manifest.ReviewProtocols {
		fmt.Fprintf(&b, "  - %s: %s\n", item.Name, item.Path)
	}
	return b.String()
}

package sprint

import (
	"fmt"
	"path/filepath"
	"regexp"
	"strings"
)

type PlanManifest struct {
	ProjectSlug        string
	SprintSlug         string
	SprintRoot         string
	RequirementsPath   string
	SprintIndexPath    string
	HandbookPath       string
	ReasoningPath      string
	OutputPath         string
	ReasoningTemplates []ReasoningTemplateEntry
	DecisionNames      []string
	EvidencePhrases    []string
}

func BuildPlanManifest(root string, sp Sprint, inputs PlanningInputs, catalogSprintIndex string, reasoning string) (PlanManifest, []ValidationFinding) {
	_ = root
	index, findings := ParseSprintIndex(catalogSprintIndex)
	manifest := PlanManifest{
		ProjectSlug:      sp.Project,
		SprintSlug:       sp.Slug,
		SprintRoot:       filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug)),
		RequirementsPath: ArtifactRelPath(sp, StageRequirements),
		SprintIndexPath:  ArtifactRelPath(sp, StageSprintIndex),
		HandbookPath:     ArtifactRelPath(sp, StageTechnicalHandbook),
		ReasoningPath:    ArtifactRelPath(sp, StageReasoning),
		OutputPath:       ArtifactRelPath(sp, StagePlan),
		DecisionNames:    extractReasoningDecisions(reasoning),
		EvidencePhrases:  extractReasoningEvidence(reasoning),
	}
	for _, item := range index.ReasoningTemplates {
		manifest.ReasoningTemplates = append(manifest.ReasoningTemplates, ReasoningTemplateEntry{Name: item.Name, OutputPath: item.Path, Why: item.Why})
	}
	sortSprintFindings(findings)
	return manifest, findings
}

func ValidatePlanContent(content string, manifest PlanManifest) []ValidationFinding {
	var findings []ValidationFinding
	if strings.TrimSpace(content) == "" {
		return []ValidationFinding{finding("plan.md", "", manifest.OutputPath, "empty plan", "file has no content", "Generate or write the required plan sections.")}
	}
	if containsPlaceholder(content) {
		findings = append(findings, finding("plan.md", "", manifest.OutputPath, "placeholder content", "file still contains placeholder markers", "Replace placeholders with concrete sprint plan content."))
	}
	sections := markdownSections(content)
	required := []string{"Decisions To Execute", "Tasks", "Evidence Checklist", "Risks And Blockers", "Completion Criteria"}
	for _, section := range required {
		if strings.TrimSpace(sections[section]) == "" {
			findings = append(findings, finding(section, "", manifest.OutputPath, "missing required section", "section was not found or has no content", "Add the required plan section."))
		}
	}
	if !strings.Contains(content, manifest.ReasoningPath) && !strings.Contains(content, "reasoning.md") {
		findings = append(findings, finding("Reasoning Source", "", manifest.OutputPath, "missing reasoning reference", "plan does not cite reasoning.md", "Reference reasoning.md as the source of decisions."))
	}
	decisionSection := sections["Decisions To Execute"]
	for _, decision := range manifest.DecisionNames {
		if decision != "" && !strings.Contains(decisionSection, decision) && !strings.Contains(content, decision) {
			findings = append(findings, finding("Decisions To Execute", decision, manifest.OutputPath, "missing reasoning decision trace", "plan does not trace a final reasoning decision", "List each final reasoning decision that the plan executes."))
		}
	}
	taskSection := sections["Tasks"]
	if !strings.Contains(taskSection, "- [ ]") && !strings.Contains(taskSection, "- [x]") && !strings.Contains(taskSection, "- [X]") && !strings.Contains(taskSection, "- [/]") {
		findings = append(findings, finding("Tasks", "", manifest.OutputPath, "missing task checklist", "tasks section has no Markdown checkbox items", "Add executable sprint task checkboxes."))
	}
	if len(manifest.DecisionNames) > 0 && containsTaskWithoutTrace(taskSection) {
		findings = append(findings, finding("Tasks", "", manifest.OutputPath, "untraced task", "a task does not cite a decision or acceptance criterion", "Trace each implementation task to reasoning decisions or acceptance evidence."))
	}
	evidenceSection := sections["Evidence Checklist"]
	if !strings.Contains(evidenceSection, "- [ ]") && !strings.Contains(evidenceSection, "- [x]") && !strings.Contains(evidenceSection, "- [X]") {
		findings = append(findings, finding("Evidence Checklist", "", manifest.OutputPath, "missing evidence checklist", "evidence section has no Markdown checkbox items", "Add explicit verification and evidence checkboxes."))
	}
	forbidden := forbiddenPlanStageContent(content)
	for _, phrase := range forbidden {
		findings = append(findings, finding("Deferred Scope", "", manifest.OutputPath, "forbidden deferred-stage behavior", phrase, "Keep implementation execution, smoke, review automation, issues, and Git mutation out of current Phase 2 CLI behavior."))
	}
	sortSprintFindings(findings)
	return findings
}

func extractReasoningDecisions(content string) []string {
	re := regexp.MustCompile(`(?m)^#{2,3}\s+Decision\s+\d+:\s*(.+?)\s*$`)
	matches := re.FindAllStringSubmatch(content, -1)
	out := make([]string, 0, len(matches))
	for _, match := range matches {
		out = append(out, strings.TrimSpace(match[1]))
	}
	return out
}

func extractReasoningEvidence(content string) []string {
	sections := markdownSections(content)
	evidence := sections["Expected Evidence"]
	var out []string
	for _, line := range strings.Split(evidence, "\n") {
		line = strings.TrimSpace(strings.TrimLeft(line, "-| "))
		if line == "" || strings.HasPrefix(line, "---") {
			continue
		}
		if strings.Contains(strings.ToLower(line), "test") || strings.Contains(strings.ToLower(line), "review") || strings.Contains(strings.ToLower(line), "flow") {
			out = append(out, line)
		}
	}
	return out
}

func containsTaskWithoutTrace(section string) bool {
	var taskBlock []string
	flush := func() bool {
		if len(taskBlock) == 0 {
			return false
		}
		lower := strings.ToLower(strings.Join(taskBlock, "\n"))
		return !strings.Contains(lower, "decision") &&
			!strings.Contains(lower, "ac-") &&
			!strings.Contains(lower, "evidence") &&
			!strings.Contains(lower, "verification") &&
			!strings.Contains(lower, "executes:")
	}
	for _, line := range strings.Split(section, "\n") {
		if isTopLevelTaskCheckbox(line) {
			if flush() {
				return true
			}
			taskBlock = []string{line}
			continue
		}
		if len(taskBlock) > 0 {
			taskBlock = append(taskBlock, line)
		}
	}
	return flush()
}

func isTopLevelTaskCheckbox(line string) bool {
	if strings.TrimLeft(line, " \t") != line {
		return false
	}
	trimmed := strings.TrimSpace(line)
	if len(trimmed) < len("- [ ]") {
		return false
	}
	lower := strings.ToLower(trimmed)
	return strings.HasPrefix(lower, "- [ ]") || strings.HasPrefix(lower, "- [x]") || strings.HasPrefix(lower, "- [/]")
}

func forbiddenPlanStageContent(content string) []string {
	lower := strings.ToLower(content)
	patterns := []string{
		"flow --to implementation",
		"flow --to execute",
		"flow --to smoke",
		"flow --to review",
		"flow --to issues",
		"generate .run-state.json",
		"create .run-state.json",
		"write .run-state.json",
		"git commit",
		"git push",
	}
	var out []string
	for _, pattern := range patterns {
		if strings.Contains(lower, pattern) {
			out = append(out, fmt.Sprintf("contains %q", pattern))
		}
	}
	return out
}

package sprint

import (
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type FSStore struct {
	Root string
}

type ArtifactSnapshot struct {
	Files               map[PlanningStage]bool
	AreaReasoningFiles  []string
	NoReasoningSelected bool
}

type PlanningInputs struct {
	Requirements string
	CodeContext  string
	SprintIndex  string
	ProjectIndex string
	Docs         []string
}

func NewFSStore(root string) FSStore {
	return FSStore{Root: root}
}

func (s FSStore) ReadArtifacts(sp Sprint) (ArtifactSnapshot, error) {
	snap := ArtifactSnapshot{Files: map[PlanningStage]bool{}}
	for _, stage := range []PlanningStage{StageRequirements, StageCodeContext, StageSprintIndex, StageTechnicalHandbook, StageReasoning, StagePlan} {
		path, err := ArtifactPath(s.Root, sp, stage)
		if err != nil {
			return ArtifactSnapshot{}, err
		}
		ok, err := nonEmptyFile(path)
		if err != nil {
			return ArtifactSnapshot{}, err
		}
		if ok && stage == StageRequirements {
			data, readErr := os.ReadFile(path)
			if readErr != nil {
				return ArtifactSnapshot{}, readErr
			}
			ok = len(ValidateRequirementsContent(string(data))) == 0
		}
		if ok && stage == StageCodeContext {
			data, readErr := os.ReadFile(path)
			if readErr != nil {
				return ArtifactSnapshot{}, readErr
			}
			ok = len(ValidateCodeContextContent(string(data))) == 0
		}
		snap.Files[stage] = ok
	}
	reasoningDir, err := ArtifactPath(s.Root, sp, StageAreaReasoning)
	if err != nil {
		return ArtifactSnapshot{}, err
	}
	entries, err := readOptionalDir(reasoningDir)
	if err != nil {
		return ArtifactSnapshot{}, err
	}
	for _, entry := range entries {
		if entry.IsDir() || isHidden(entry.Name()) || strings.ToLower(filepath.Ext(entry.Name())) != ".md" {
			continue
		}
		full := filepath.Join(reasoningDir, entry.Name())
		ok, err := nonEmptyFile(full)
		if err != nil {
			return ArtifactSnapshot{}, err
		}
		if ok {
			snap.AreaReasoningFiles = append(snap.AreaReasoningFiles, entry.Name())
		}
	}
	sort.Strings(snap.AreaReasoningFiles)
	indexPath, err := ArtifactPath(s.Root, sp, StageSprintIndex)
	if err != nil {
		return ArtifactSnapshot{}, err
	}
	content, err := os.ReadFile(indexPath)
	if err == nil {
		snap.NoReasoningSelected = explicitlyNoReasoningTemplates(string(content))
	}
	return snap, nil
}

func (s FSStore) ReadPlanningInputs(sp Sprint) (PlanningInputs, error) {
	var inputs PlanningInputs
	req, err := ArtifactPath(s.Root, sp, StageRequirements)
	if err != nil {
		return PlanningInputs{}, err
	}
	if data, err := os.ReadFile(req); err == nil {
		inputs.Requirements = string(data)
	} else {
		return PlanningInputs{}, err
	}
	contextPath, err := ArtifactPath(s.Root, sp, StageCodeContext)
	if err != nil {
		return PlanningInputs{}, err
	}
	if data, readErr := os.ReadFile(contextPath); readErr == nil {
		inputs.CodeContext = string(data)
	} else if !os.IsNotExist(readErr) {
		return PlanningInputs{}, readErr
	}
	idx, err := ArtifactPath(s.Root, sp, StageSprintIndex)
	if err != nil {
		return PlanningInputs{}, err
	}
	if data, err := os.ReadFile(idx); err == nil {
		inputs.SprintIndex = string(data)
	} else if !os.IsNotExist(err) {
		return PlanningInputs{}, err
	}
	projectRoot, err := workspace.ResolveInside(s.Root, filepath.ToSlash(filepath.Join("projects", sp.Project)))
	if err != nil {
		return PlanningInputs{}, err
	}
	data, err := os.ReadFile(filepath.Join(projectRoot, "project-index.md"))
	if err != nil {
		return PlanningInputs{}, err
	}
	inputs.ProjectIndex = string(data)
	p := project.Project{Name: sp.Project, Path: projectRoot}
	files, err := project.NewFSStore(s.Root).ReadProjectFiles(p)
	if err != nil {
		return PlanningInputs{}, err
	}
	inputs.Docs = files.MarkdownDocs
	return inputs, nil
}

func (s FSStore) ReadArtifact(sp Sprint, stage PlanningStage) (string, error) {
	path, err := ArtifactPath(s.Root, sp, stage)
	if err != nil {
		return "", err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func (s FSStore) ReadFile(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func nonEmptyFile(path string) (bool, error) {
	info, err := os.Stat(path)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return !info.IsDir() && info.Size() > 0, nil
}

func explicitlyNoReasoningTemplates(content string) bool {
	lower := strings.ToLower(content)
	needles := []string{
		"no reasoning templates",
		"none selected",
		"no templates selected",
		"selected reasoning templates\n\nnone",
	}
	for _, needle := range needles {
		if strings.Contains(lower, needle) {
			return true
		}
	}
	return false
}

