			return FlowState{}, err
		}
		return state, nil
	}
	path, err := FlowStatePath(root, s)
	if err != nil {
		return FlowState{}, err
	}
	content, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return FlowState{}, fmt.Errorf("%w: %s", ErrFlowStateMissing, path)
		}
		return FlowState{}, fmt.Errorf("read flow state %s: %w", path, err)
	}
	var header struct {
		SchemaVersion int `json:"schemaVersion"`
	}
	if err := json.Unmarshal(content, &header); err != nil {
		return FlowState{}, fmt.Errorf("%w: %s: %w", ErrFlowStateMalformed, path, err)
	}
	if header.SchemaVersion == 0 {
		return FlowState{}, fmt.Errorf("%w: %s: missing schemaVersion", ErrFlowStateMalformed, path)
	}
	if header.SchemaVersion != FlowStateSchemaVersion && header.SchemaVersion != PreviousFlowStateSchemaVersion {
		return FlowState{}, fmt.Errorf("%w: %s: schemaVersion %d; restore version %d or regenerate state", ErrFlowStateUnsupported, path, header.SchemaVersion, FlowStateSchemaVersion)
	}
	var state FlowState
	dec := json.NewDecoder(bytes.NewReader(content))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&state); err != nil {
		return FlowState{}, fmt.Errorf("%w: %s: %w", ErrFlowStateMalformed, path, err)
	}
	var trailing any
	if err := dec.Decode(&trailing); err == nil {
		return FlowState{}, fmt.Errorf("%w: %s: multiple JSON values", ErrFlowStateMalformed, path)
	} else if !errors.Is(err, io.EOF) {
		return FlowState{}, fmt.Errorf("%w: %s: trailing JSON: %v", ErrFlowStateMalformed, path, err)
	}
	if header.SchemaVersion == PreviousFlowStateSchemaVersion {
		state = migrateFlowStateV1(root, s, state)
		if err := ValidateFlowState(root, s, state, path); err != nil {
			return FlowState{}, err
		}
	}
	if header.SchemaVersion == FlowStateSchemaVersion && isPreCodeContextStages(state.Stages) {
		state.Stages = interpretPreCodeContextStages(s, state.Stages)
	}
	if err := ValidateFlowState(root, s, state, path); err != nil {
		return FlowState{}, err
	}
	return state, nil
}

func isPreCodeContextStages(stages []StageState) bool {
	if len(stages) != len(PlanningStages())-1 {
		return false
	}
	legacy := []PlanningStage{StageRequirements, StageSprintIndex, StageTechnicalHandbook, StageAreaReasoning, StageReasoning, StagePlan}
	for i := range legacy {
		if stages[i].Stage != legacy[i] {
			return false
		}
	}
	return true
}

func interpretPreCodeContextStages(sp Sprint, stages []StageState) []StageState {
	out := make([]StageState, 0, len(stages)+1)
	out = append(out, stages[0])
	inserted := StageState{Stage: StageCodeContext, Status: StatusMissing, Path: ArtifactRelPath(sp, StageCodeContext)}
	if stages[0].Status == StatusComplete {
		inserted.Status = StatusReady
		for _, later := range stages[1:] {
			if later.Status != StatusMissing {
				inserted.Status = StatusSkipped
				inserted.LastRunAt = stages[0].LastRunAt
				break
			}
		}
	}
	out = append(out, inserted)
	out = append(out, stages[1:]...)
	return out
}

func preCodeContextFlowState(root string, sp Sprint) bool {
	path, err := FlowStatePath(root, sp)
	if err != nil {
		return false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	var state FlowState
	return json.Unmarshal(data, &state) == nil && state.SchemaVersion == FlowStateSchemaVersion && isPreCodeContextStages(state.Stages)
}

// legacyFlowState reports the original versioned map-based planning state.
// It predates durable review/smoke attempt ownership, so recovery has no live
// attempt to reconcile and must preserve the file for compatibility.
func legacyFlowState(root string, s Sprint) bool {
	path, err := FlowStatePath(root, s)
	if err != nil {
		return false
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	var header struct {
		SchemaVersion int `json:"schemaVersion"`
		Version       int `json:"version"`
	}
	if err := json.Unmarshal(content, &header); err != nil {
		return false
	}
	return header.SchemaVersion == 0 && header.Version == 1
}

func migrateFlowStateV1(root string, sp Sprint, state FlowState) FlowState {
	state.SchemaVersion = FlowStateSchemaVersion
	if isPreCodeContextStages(state.Stages) {
		state.Stages = interpretPreCodeContextStages(sp, state.Stages)
	}
	if state.Review != nil {
		r := state.Review
		r.Stale = true
		if r.Status == ReviewCompleted {
			digest, _ := hashFile(mustArtifactPath(root, sp, StageReview))
			if digest == "" {
				digest = "legacy-unverifiable"
			}
			if r.Fingerprint == "" {
				r.Fingerprint = "legacy-unverifiable"
			}
			completedAt := derefTime(r.LastRunAt)
			if completedAt.IsZero() {
				completedAt = state.UpdatedAt
			}
			r.ArtifactDigest = digest
			r.LastComplete = &ReviewCompletion{Verdict: r.Verdict, Artifact: r.Path, ArtifactDigest: digest, InputFingerprint: r.Fingerprint, CompletedAt: completedAt}
		}
	}
	if state.Smoke != nil {
		sm := state.Smoke
		sm.Stale = true
		if sm.Status == SmokeCompleted {
			digest, _ := hashFile(mustArtifactPath(root, sp, StageSmoke))
			if digest == "" {
				digest = "legacy-unverifiable"
			}
			completedAt := derefTime(sm.LastRunAt)
			if completedAt.IsZero() {
				completedAt = state.UpdatedAt
			}
			sm.ArtifactDigest = digest
			sm.InputFingerprint = "legacy-unverifiable"
			sm.LastComplete = &SmokeCompletion{Verdict: sm.Verdict, Artifact: sm.Path, ArtifactDigest: digest, InputFingerprint: sm.InputFingerprint, CompletedAt: completedAt, RunID: sm.RunID, EvidenceID: sm.EvidenceID}
		}
	}
	return state
}

func derefTime(value *time.Time) time.Time {
	if value == nil {
		return time.Time{}
	}
	return value.UTC()
}

func SaveFlowState(root string, s Sprint, state FlowState) error {
	// Planning-stage refreshes must not erase the last complete verification
	// evidence. Explicit stage writers load and replace their own record.
	if state.Review == nil || state.Smoke == nil || state.QA == nil {
		if prior, err := LoadFlowState(root, s); err == nil {
			if state.Review == nil {
				state.Review = prior.Review
			}
			if state.Smoke == nil {
				state.Smoke = prior.Smoke
			}
			if state.QA == nil {
				state.QA = prior.QA
			}
		} else if !errors.Is(err, ErrFlowStateMissing) {
			return err
		}
	}
	if authoritative, err := FlowStateInDatabase(root, s); err != nil {
		return err
	} else if authoritative {
		if err := saveFlowStateDatabase(root, s, state); err != nil {
			return err
		}
		if !flowStateCheckpoint(state) {
			return nil
		}
		return saveFlowStateWithHooks(root, s, state, atomicWriteHooks{})
	}
	return saveFlowStateWithHooks(root, s, state, atomicWriteHooks{})
}

func flowStateCheckpoint(state FlowState) bool {
	for _, stage := range state.Stages {
		if stage.Status != StatusComplete && stage.Status != StatusFailed && stage.Status != StatusSkipped {
			return false
		}
	}
	return len(state.Stages) > 0
}

func saveFlowStateWithHooks(root string, s Sprint, state FlowState, hooks atomicWriteHooks) error {
	path, err := FlowStatePath(root, s)
	if err != nil {
		return err
	}
	state.UpdatedAt = time.Now().UTC()
	if err := ValidateFlowState(root, s, state, path); err != nil {
		return err
	}
	content, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal flow state %s: %w", path, err)
	}
	content = append(content, '\n')
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create flow state directory %s: %w", filepath.Dir(path), err)
	}
	temp, err := os.CreateTemp(filepath.Dir(path), ".flow-state.*.tmp")
	if err != nil {
		return fmt.Errorf("create temporary flow state %s: %w", path, err)
	}
	tempPath := temp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tempPath)
		}
	}()
	if _, err := temp.Write(content); err != nil {
		_ = temp.Close()
		return fmt.Errorf("write temporary flow state %s: %w", tempPath, err)
	}
	if err := temp.Sync(); err != nil {
		_ = temp.Close()
		return fmt.Errorf("flush temporary flow state %s: %w", tempPath, err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("close temporary flow state %s: %w", tempPath, err)
	}
	if hooks.BeforeRename != nil {
		if err := hooks.BeforeRename(path); err != nil {
			return fmt.Errorf("prepare flow state rename %s: %w", path, err)
		}
	}
	if err := os.Rename(tempPath, path); err != nil {
		return fmt.Errorf("rename flow state %s: %w", path, err)
	}
	cleanup = false
	syncDir(filepath.Dir(path))
	return nil
}

func ValidateFlowState(root string, s Sprint, state FlowState, path string) error {
	if state.SchemaVersion == 0 {
		return fmt.Errorf("%w: %s: missing schemaVersion", ErrFlowStateMalformed, path)
	}
	if state.SchemaVersion != FlowStateSchemaVersion {
		return fmt.Errorf("%w: %s: schemaVersion %d", ErrFlowStateUnsupported, path, state.SchemaVersion)
	}
	if state.Project == "" || state.Sprint == "" || state.UpdatedAt.IsZero() {
		return fmt.Errorf("%w: %s: missing required top-level fields", ErrFlowStateMalformed, path)
	}
	if state.Project != s.Project {
		return fmt.Errorf("%w: %s: project mismatch %q", ErrFlowStateMalformed, path, state.Project)
	}
	if state.Sprint != s.Slug {
		return fmt.Errorf("%w: %s: sprint mismatch %q", ErrFlowStateMalformed, path, state.Sprint)
	}
	if len(state.Stages) != len(PlanningStages()) {
		return fmt.Errorf("%w: %s: expected %d stages", ErrFlowStateMalformed, path, len(PlanningStages()))
	}
	seen := map[PlanningStage]bool{}
	for i, stage := range state.Stages {
		if stage.Stage != PlanningStages()[i] {
			return fmt.Errorf("%w: %s: stage %d is %q; expected %q", ErrFlowStateMalformed, path, i, stage.Stage, PlanningStages()[i])
		}
		if !ValidStage(stage.Stage) {
			return fmt.Errorf("%w: %s: unsupported stage %q", ErrFlowStateMalformed, path, stage.Stage)
		}
		if seen[stage.Stage] {
			return fmt.Errorf("%w: %s: duplicate stage %q", ErrFlowStateMalformed, path, stage.Stage)
		}
		seen[stage.Stage] = true
		if !ValidStatus(stage.Status) {
			return fmt.Errorf("%w: %s: stage %q has unsupported status %q", ErrFlowStateMalformed, path, stage.Stage, stage.Status)
		}
		if stage.Path == "" {
			return fmt.Errorf("%w: %s: stage %d missing path", ErrFlowStateMalformed, path, i)
		}
		if filepath.IsAbs(stage.Path) || strings.HasPrefix(filepath.ToSlash(filepath.Clean(filepath.FromSlash(stage.Path))), "../") {
			return fmt.Errorf("%w: %s: stage %q has unsafe path", ErrFlowStateMalformed, path, stage.Stage)
		}
		if _, err := resolveSprintContained(root, s, stage.Path); err != nil {
			return fmt.Errorf("%w: %s: stage %q has unsafe path: %w", ErrFlowStateMalformed, path, stage.Stage, err)
		}
		if strings.ContainsAny(stage.Error, "\x00\r\n") {
			return fmt.Errorf("%w: %s: stage %q has unsafe error detail", ErrFlowStateMalformed, path, stage.Stage)
		}
		switch stage.LatestOutcome {
		case "", "failed", "cancelled", "interrupted", "cleanup_uncertain":
		default:
			return fmt.Errorf("%w: %s: stage %q has unsupported latest outcome %q", ErrFlowStateMalformed, path, stage.Stage, stage.LatestOutcome)
		}
	}
	for _, expected := range PlanningStages() {
		if !seen[expected] {
			return fmt.Errorf("%w: %s: missing stage %q", ErrFlowStateMalformed, path, expected)
		}
	}
	if state.Review != nil {
		if err := validateReviewStageState(root, s, *state.Review, path); err != nil {
			return err
		}
	}
	if state.Smoke != nil {
		if err := validateSmokeStageState(root, s, *state.Smoke, path); err != nil {
			return err
		}
	}
	if state.QA != nil {
		if err := validateQAFlowSummary(root, s, *state.QA, path); err != nil {
			return err
		}
	}
	return nil
}

func validateQAFlowSummary(root string, s Sprint, summary QAFlowSummary, path string) error {
	if !containsQAPhase(summary.Phase) || summary.CompletedShards < 0 || summary.TotalShards < 0 || summary.CompletedShards > summary.TotalShards || summary.Confirmed < 0 || summary.Blocked < 0 {
		return fmt.Errorf("%w: %s: invalid QA summary", ErrFlowStateMalformed, path)
	}
	if summary.StatePath == "" || !validFingerprint(summary.StateDigest) || strings.TrimSpace(summary.NextAction) == "" {
		return fmt.Errorf("%w: %s: incomplete QA summary pointer", ErrFlowStateMalformed, path)
	}
	resolved, err := resolveSprintContained(root, s, summary.StatePath)
	if err != nil || filepath.Base(resolved) != "state.json" || filepath.Base(filepath.Dir(resolved)) != "verification" {
		return fmt.Errorf("%w: %s: unsafe QA summary pointer", ErrFlowStateMalformed, path)
	}
	if summary.CurrentAttemptID != "" && !validQAID(summary.CurrentAttemptID) {
		return fmt.Errorf("%w: %s: invalid QA summary attempt ID", ErrFlowStateMalformed, path)
	}
	return nil
}

func NewFlowState(s Sprint, stages []StageState, now time.Time) FlowState {
	if now.IsZero() {
		now = time.Now().UTC()
	}
	return FlowState{
		SchemaVersion: FlowStateSchemaVersion,
		Project:       s.Project,
		Sprint:        s.Slug,
		UpdatedAt:     now.UTC(),
		Stages:        stages,
	}
}

func syncDir(path string) {
	dir, err := os.Open(path)
	if err != nil {
		return
	}
	defer dir.Close()
	_ = dir.Sync()
}

package sprint

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

const sprintWorkspaceSchemaVersion = 1

type SprintWorkspace struct {
	SchemaVersion int       `json:"schemaVersion"`
	SourceRoot    string    `json:"sourceRoot"`
	Path          string    `json:"path"`
	Branch        string    `json:"branch"`
	Baseline      string    `json:"baseline"`
	CreatedAt     time.Time `json:"createdAt"`
}

func sprintWorkspacePath(sp Sprint) string { return filepath.Join(sp.Path, ".workspace.json") }

func ResolveExecuteTarget(workspaceRoot, projectIndexContent string) (ExecuteTargetRef, []ValidationFinding) {
	target := extractTargetImplementationDirectory(projectIndexContent)
	if target == "" {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", "", "missing target implementation directory", "project-index.md does not declare a target implementation directory", "Set Project Scope / Target Implementation Directory to the approved implementation repository.")}
	}
	clean := filepath.Clean(target)
	if !filepath.IsAbs(clean) {
		if strings.TrimSpace(workspaceRoot) == "" {
			return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "relative target has no workspace root", "the target cannot be resolved without the UltraPlan workspace root", "Run the command from a valid UltraPlan workspace or use an absolute target path.")}
		}
		clean = filepath.Join(workspaceRoot, clean)
	}
	resolved, err := filepath.Abs(clean)
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target path cannot be resolved", err.Error(), "Use a valid absolute path or a path relative to the UltraPlan workspace root.")}
	}
	clean = filepath.Clean(resolved)
	info, err := os.Stat(clean)
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target root unavailable", err.Error(), "Create or restore the approved target repository before execute.")}
	}
	if !info.IsDir() {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target root is not a directory", "path exists but is not a directory", "Use the approved target repository directory.")}
	}
	return ExecuteTargetRef{Path: clean, Source: "project-index.md"}, nil
}

func (s Service) resolveSprintTarget(sp Sprint, projectIndex string, create bool) (ExecuteTargetRef, []ValidationFinding) {
	if s.codeContextTarget != nil {
		return s.codeContextTarget(projectIndex)
	}
	source, findings := ResolveExecuteTarget(s.root, projectIndex)
	if len(findings) > 0 {
		return ExecuteTargetRef{}, findings
	}
	record, err := loadSprintWorkspace(sp)
	if err == nil {
		if validateErr := validateSprintWorkspace(record, source.Path); validateErr != nil {
			return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", workspace.Rel(s.root, sprintWorkspacePath(sp)), "invalid sprint workspace", validateErr.Error(), "Restore the recorded worktree or explicitly recreate the sprint workspace.")}
		}
		return ExecuteTargetRef{Path: record.Path, Source: ".workspace.json"}, nil
	}
	if !os.IsNotExist(err) {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", workspace.Rel(s.root, sprintWorkspacePath(sp)), "unreadable sprint workspace", err.Error(), "Repair or remove the malformed sprint workspace record.")}
	}
	if !create {
		return source, nil
	}
	record, err = createSprintWorkspace(sp, source.Path, s.now().UTC())
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", source.Path, "cannot create sprint workspace", err.Error(), "Commit or stash source changes, remove any conflicting branch or worktree, then retry.")}
	}
	return ExecuteTargetRef{Path: record.Path, Source: ".workspace.json"}, nil
}

func loadSprintWorkspace(sp Sprint) (SprintWorkspace, error) {
	data, err := os.ReadFile(sprintWorkspacePath(sp))
	if err != nil {
		return SprintWorkspace{}, err
	}
	var record SprintWorkspace
	if err := json.Unmarshal(data, &record); err != nil {
		return SprintWorkspace{}, fmt.Errorf("decode sprint workspace: %w", err)
	}
	if record.SchemaVersion != sprintWorkspaceSchemaVersion || record.SourceRoot == "" || record.Path == "" || record.Branch == "" || record.Baseline == "" {
		return SprintWorkspace{}, fmt.Errorf("invalid sprint workspace record")
	}
	return record, nil
}

func validateSprintWorkspace(record SprintWorkspace, source string) error {
	if filepath.Clean(record.SourceRoot) != filepath.Clean(source) {
		return fmt.Errorf("project target changed from %q to %q", record.SourceRoot, source)
	}
	info, err := os.Stat(record.Path)
	if err != nil {
		return fmt.Errorf("worktree unavailable: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("worktree path is not a directory")
	}
	sourceCommon, err := gitCommonDirectory(source)
	if err != nil {
		return fmt.Errorf("source Git metadata unavailable: %w", err)
	}
	workspaceCommon, err := gitCommonDirectory(record.Path)
	if err != nil || workspaceCommon != sourceCommon {
		return fmt.Errorf("worktree belongs to a different Git repository")
	}
	branch, err := gitOutput(record.Path, "branch", "--show-current")
	if err != nil || strings.TrimSpace(branch) != record.Branch {
		return fmt.Errorf("worktree is not on recorded branch %q", record.Branch)
	}
	return nil
}

func gitCommonDirectory(dir string) (string, error) {
	common, err := gitOutput(dir, "rev-parse", "--git-common-dir")
	if err != nil {
		return "", err
	}
	if !filepath.IsAbs(common) {
		common = filepath.Join(dir, common)
	}
	return filepath.Abs(filepath.Clean(common))
}

func createSprintWorkspace(sp Sprint, source string, now time.Time) (SprintWorkspace, error) {
	root, err := gitOutput(source, "rev-parse", "--show-toplevel")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("target is not a Git worktree: %w", err)
	}
	root = filepath.Clean(root)
	if filepath.Clean(source) != root {
		return SprintWorkspace{}, fmt.Errorf("target must be the Git worktree root %q", root)
	}
	dirty, err := gitOutput(source, "status", "--porcelain", "--untracked-files=normal")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("inspect target status: %w", err)
	}
	if strings.TrimSpace(dirty) != "" {
		return SprintWorkspace{}, fmt.Errorf("target has uncommitted changes")
	}
	baseline, err := gitOutput(source, "rev-parse", "HEAD")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("resolve target HEAD: %w", err)
	}
	branch := "ultraplan/" + safeGitComponent(sp.Project) + "/" + safeGitComponent(sp.Slug)
	parent := filepath.Join(filepath.Dir(root), "."+filepath.Base(root)+"-ultraplan-worktrees")
	path := filepath.Join(parent, safeGitComponent(sp.Project), safeGitComponent(sp.Slug))
	if _, err := os.Lstat(path); !os.IsNotExist(err) {
		return SprintWorkspace{}, fmt.Errorf("worktree path already exists: %s", path)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return SprintWorkspace{}, fmt.Errorf("create worktree parent: %w", err)
	}
	cmd := exec.Command("git", "-C", source, "worktree", "add", "-b", branch, path, strings.TrimSpace(baseline))
	if output, err := cmd.CombinedOutput(); err != nil {
		return SprintWorkspace{}, fmt.Errorf("git worktree add: %s: %w", strings.TrimSpace(string(output)), err)
	}
	record := SprintWorkspace{SchemaVersion: sprintWorkspaceSchemaVersion, SourceRoot: root, Path: path, Branch: branch, Baseline: strings.TrimSpace(baseline), CreatedAt: now}
	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return SprintWorkspace{}, err
	}
	data = append(data, '\n')
	if err := atomicWriteFile(sprintWorkspacePath(sp), data); err != nil {
		_ = exec.Command("git", "-C", source, "worktree", "remove", path).Run()
		_ = exec.Command("git", "-C", source, "branch", "-D", branch).Run()
		return SprintWorkspace{}, fmt.Errorf("persist sprint workspace: %w", err)
	}
	return record, nil
}

func gitOutput(dir string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
	}
	return strings.TrimSpace(string(output)), nil
}

func safeGitComponent(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	value = regexp.MustCompile(`[^a-z0-9._-]+`).ReplaceAllString(value, "-")
	value = strings.Trim(value, ".-")
	if value == "" {
		return "sprint"
	}
	return value
}

func ValidateExecuteWorkdir(target ExecuteTargetRef, workdir string) error {
	if target.Path == "" {
		return fmt.Errorf("missing execute target")
	}
	if workdir == "" {
		return fmt.Errorf("missing execute workdir")
	}
	targetPath := filepath.Clean(target.Path)
	workPath := filepath.Clean(workdir)
	if !filepath.IsAbs(workPath) {
		return fmt.Errorf("execute workdir %q must be absolute", workdir)
	}
	if !inside(targetPath, workPath) {
		return fmt.Errorf("execute workdir %q escapes approved target %q", workdir, target.Path)
	}
	return nil
}

func ExecuteSafetyInstructions(target ExecuteTargetRef) []string {
	return []string{
		"Work only inside approved target: " + target.Path,
		"Do not create smoke.md, smoke.json, generated review.md, issues.md, or issues.json.",
		"Do not run or request Git mutation: add, commit, push, branch, checkout, reset, PR creation, or issue tracking.",
		"Do not schedule cross-sprint work, launch a TUI, or build hosted/browser UI behavior.",
	}
}

func extractTargetImplementationDirectory(content string) string {
	re := regexp.MustCompile(`(?im)^\s*-\s+\*\*Target Implementation Directory:\*\*\s*(.+?)\s*$`)
	if match := re.FindStringSubmatch(content); len(match) == 2 {
		return strings.Trim(strings.TrimSpace(match[1]), "`")
	}
	re = regexp.MustCompile(`(?im)^\s*-\s+Target Implementation Directory:\s*(.+?)\s*$`)
	if match := re.FindStringSubmatch(content); len(match) == 2 {
		return strings.Trim(strings.TrimSpace(match[1]), "`")
	}
	return ""
}

package sprint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/project"
)

const (
	runtimeMetricsSchemaVersion = 1
	runtimeMetricsFileName      = ".runtime-metrics.json"
	maxRuntimeMetricRecords     = 512
)

type RuntimeTokenMetric struct {
	Known bool  `json:"known"`
	Value int64 `json:"value,omitempty"`
}

type SprintRuntimeMetric struct {
	Stage              PlanningStage      `json:"stage"`
	Operation          string             `json:"operation,omitempty"`
	Task               string             `json:"task,omitempty"`
	Coverage           string             `json:"coverage,omitempty"`
	RunID              string             `json:"run_id,omitempty"`
	SessionID          string             `json:"session_id,omitempty"`
	Status             string             `json:"status,omitempty"`
	Provider           string             `json:"provider,omitempty"`
	Model              string             `json:"model,omitempty"`
	PromptBytes        int                `json:"prompt_bytes"`
	SharedPrefixBytes  int                `json:"shared_prefix_bytes,omitempty"`
	StageSuffixBytes   int                `json:"stage_suffix_bytes"`
	SharedPrefixDigest string             `json:"shared_prefix_sha256,omitempty"`
	CacheKey           string             `json:"cache_key,omitempty"`
	InputTokens        RuntimeTokenMetric `json:"input_tokens"`
	OutputTokens       RuntimeTokenMetric `json:"output_tokens"`
	ReasoningTokens    RuntimeTokenMetric `json:"reasoning_tokens"`
	CacheReadTokens    RuntimeTokenMetric `json:"cache_read_tokens"`
	CacheWriteTokens   RuntimeTokenMetric `json:"cache_write_tokens"`
	TotalTokens        RuntimeTokenMetric `json:"total_tokens"`
	Turns              RuntimeTokenMetric `json:"turns"`
	CostAmount         float64            `json:"cost_amount,omitempty"`
	CostCurrency       string             `json:"cost_currency,omitempty"`
	CostEstimated      bool               `json:"cost_estimated,omitempty"`
	CostSource         string             `json:"cost_source,omitempty"`
	StartedAt          time.Time          `json:"started_at,omitempty"`
	FinishedAt         time.Time          `json:"finished_at,omitempty"`
	ErrorCategory      string             `json:"error_category,omitempty"`
}

type SprintRuntimeMetrics struct {
	SchemaVersion int                   `json:"schema_version"`
	Project       string                `json:"project"`
	Sprint        string                `json:"sprint"`
	UpdatedAt     time.Time             `json:"updated_at"`
	Runs          []SprintRuntimeMetric `json:"runs"`
}

func RuntimeMetricsRelPath(sp Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug, runtimeMetricsFileName))
}

func LoadRuntimeMetrics(root string, sp Sprint) (SprintRuntimeMetrics, error) {
	path, err := resolveSprintContained(root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	var metrics SprintRuntimeMetrics
	if err := json.Unmarshal(data, &metrics); err != nil {
		return SprintRuntimeMetrics{}, fmt.Errorf("decode sprint runtime metrics: %w", err)
	}
	if metrics.SchemaVersion != runtimeMetricsSchemaVersion || metrics.Project != sp.Project || metrics.Sprint != sp.Slug {
		return SprintRuntimeMetrics{}, fmt.Errorf("invalid sprint runtime metrics identity")
	}
	return metrics, nil
}

func (s Service) RuntimeMetrics(projectRef, sprintRef string) (SprintRuntimeMetrics, error) {
	projects, err := project.DiscoverProjects(s.root)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	p, err := project.ResolveProject(projects, projectRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sprints, err := DiscoverSprints(s.root, p)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sp, err := ResolveSprint(sprints, sprintRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	if !inside(p.Path, sp.Path) {
		return SprintRuntimeMetrics{}, fmt.Errorf("sprint path mismatch for %q", sp.Slug)
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		return SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}, nil
	}
	return metrics, err
}

func (s Service) startSprintRuntime(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	// Retry cleanup that was interrupted by a crash before admitting more work.
	// Recent failed stores remain available for session recovery.
	pruntime.CleanupRuntimeStores(sp.Path, 72*time.Hour, 2*1024*1024*1024, false)
	result, runErr := s.runtime.StartRun(ctx, req)
	if metricErr := s.recordRuntimeMetric(sp, stage, req, result); metricErr != nil {
		result.Warnings = append(result.Warnings, "runtime metrics were not persisted: "+safeError(metricErr))
	}
	return result, runErr
}

func (s Service) recordRuntimeMetric(sp Sprint, stage PlanningStage, req pruntime.Request, result pruntime.Result) error {
	if s.metricsMu != nil {
		s.metricsMu.Lock()
		defer s.metricsMu.Unlock()
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		metrics = SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}
	} else if err != nil {
		return err
	}
	explanation := explainComposedPrompt(req.Prompt)
	record := SprintRuntimeMetric{
		Stage: stage, Operation: req.Metadata["operation"], Task: req.Metadata["task"], Coverage: req.Metadata["coverage"],
		RunID: result.RunID, SessionID: result.SessionID, Status: result.Status, Provider: req.Provider, Model: req.Model,
		PromptBytes: explanation.TotalBytes, SharedPrefixBytes: explanation.SharedPrefixBytes, StageSuffixBytes: explanation.StageSuffixBytes,
		SharedPrefixDigest: explanation.SharedPrefixDigest, CacheKey: explanation.CacheKey,
		InputTokens: metricToken(result.Usage.InputTokensKnown, result.Usage.InputTokens), OutputTokens: metricToken(result.Usage.OutputTokensKnown, result.Usage.OutputTokens),
		ReasoningTokens: metricToken(result.Usage.ReasoningTokensKnown, result.Usage.ReasoningTokens), CacheReadTokens: metricToken(result.Usage.CacheReadTokensKnown, result.Usage.CacheReadTokens),
		CacheWriteTokens: metricToken(result.Usage.CacheWriteTokensKnown, result.Usage.CacheWriteTokens), TotalTokens: metricToken(result.Usage.TotalTokensKnown, result.Usage.TotalTokens),
		Turns: metricToken(result.Usage.TurnsKnown, result.Usage.Turns), StartedAt: result.StartedAt, FinishedAt: result.FinishedAt,
	}
	if result.EstimatedCost != nil {
		record.CostAmount, record.CostCurrency, record.CostEstimated = result.EstimatedCost.Amount, result.EstimatedCost.Currency, result.EstimatedCost.Estimate
		record.CostSource = result.EstimatedCost.Source
	}
	if result.Error != nil {
		record.ErrorCategory = result.Error.Category
	}
	metrics.Runs = append(metrics.Runs, record)
	if len(metrics.Runs) > maxRuntimeMetricRecords {
		metrics.Runs = append([]SprintRuntimeMetric(nil), metrics.Runs[len(metrics.Runs)-maxRuntimeMetricRecords:]...)
	}
	metrics.UpdatedAt = s.now().UTC()
	data, err := json.MarshalIndent(metrics, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	path, err := resolveSprintContained(s.root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return err
	}
	return atomicWriteFile(path, data)
}

func metricToken(known bool, value int64) RuntimeTokenMetric {
	return RuntimeTokenMetric{Known: known, Value: value}
}

package sprint

import (
	"context"
	"fmt"
	"path/filepath"

	"github.com/Antonio7098/ultraplan-go/internal/platform/gitpublish"
)

func (s Service) publishPlanningStage(ctx context.Context, projectRef, sprintRef string, stage PlanningStage) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	sp, err := s.resolveMutationSprint(projectRef, sprintRef)
	if err != nil {
		return nil, err
	}
	paths := []string{filepath.Join(sp.Path, "flow-state.json")}
	if stage == StageAreaReasoning {
		inputs, readErr := s.store.ReadPlanningInputs(sp)
		if readErr != nil {
			return nil, readErr
		}
		_, _, catalog, resolveErr := s.resolveSprintInputs(projectRef, sprintRef)
		if resolveErr != nil {
			return nil, resolveErr
		}
		manifest, findings := BuildReasoningManifest(s.root, sp, inputs, catalog)
		if len(findings) > 0 {
			return nil, fmt.Errorf("git publish: area-reasoning manifest is invalid")
		}
		for _, entry := range manifest.ReasoningTemplates {
			paths = append(paths, filepath.Join(s.root, filepath.FromSlash(normalizeWorkspacePath(entry.OutputPath))))
		}
	} else {
		path, pathErr := ArtifactPath(s.root, sp, stage)
		if pathErr != nil {
			return nil, pathErr
		}
		paths = append(paths, path)
	}
	if stage == StageCodeContext {
		paths = append(paths, sprintWorkspacePath(sp))
	}
	result, err := s.publisher.Publish(ctx, gitpublish.Request{
		Root: s.root, Paths: paths,
		Message:  fmt.Sprintf("ultraplan: sprint %s/%s complete %s", sp.Project, sp.Slug, stage),
		Identity: fmt.Sprintf("sprint/%s/%s/%s", sp.Project, sp.Slug, stage),
	})
	if result.Repository == "" && result.Skipped {
		return nil, err
	}
	return []gitpublish.Result{result}, err
}

func (s Service) publishExecuteStage(ctx context.Context, sp Sprint, target ExecuteTargetRef) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	identity := fmt.Sprintf("sprint/%s/%s/%s", sp.Project, sp.Slug, StageExecute)
	message := fmt.Sprintf("ultraplan: sprint %s/%s complete %s", sp.Project, sp.Slug, StageExecute)
	implementation, err := s.publisher.Publish(ctx, gitpublish.Request{Root: target.Path, All: true, Message: message, Identity: identity + "/implementation"})
	results := visiblePublication(implementation)
	if err != nil {
		return results, err
	}
	workspaceResult, err := s.publisher.Publish(ctx, gitpublish.Request{
		Root: s.root,
		Paths: []string{
			filepath.Join(sp.Path, "execute.md"),
			filepath.Join(sp.Path, ".run-state.json"),
		},
		Message: message, Identity: identity + "/workspace",
	})
	results = append(results, visiblePublication(workspaceResult)...)
	return results, err
}

func (s Service) publishReviewStage(ctx context.Context, sp Sprint) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	result, err := s.publisher.Publish(ctx, gitpublish.Request{
		Root:     s.root,
		Paths:    []string{filepath.Join(sp.Path, "review.md"), filepath.Join(sp.Path, "flow-state.json")},
		Message:  fmt.Sprintf("ultraplan: sprint %s/%s complete %s", sp.Project, sp.Slug, StageReview),
		Identity: fmt.Sprintf("sprint/%s/%s/%s", sp.Project, sp.Slug, StageReview),
	})
	return visiblePublication(result), err
}

func (s Service) publishSmokeStage(ctx context.Context, prepared smokePrepared, result SmokeResult) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	identity := fmt.Sprintf("sprint/%s/%s/%s", prepared.Sprint.Project, prepared.Sprint.Slug, StageSmoke)
	message := fmt.Sprintf("ultraplan: sprint %s/%s complete %s", prepared.Sprint.Project, prepared.Sprint.Slug, StageSmoke)
	var results []gitpublish.Result
	if len(result.AuthorChangedPaths) > 0 {
		paths := make([]string, 0, len(result.AuthorChangedPaths))
		for _, rel := range result.AuthorChangedPaths {
			paths = append(paths, filepath.Join(prepared.HarnessRoot, filepath.FromSlash(rel)))
		}
		harness, err := s.publisher.Publish(ctx, gitpublish.Request{Root: prepared.HarnessRoot, Paths: paths, Message: message, Identity: identity + "/harness"})
		results = append(results, visiblePublication(harness)...)
		if err != nil {
			return results, err
		}
	}
	workspacePaths := []string{
		filepath.Join(prepared.Sprint.Path, "smoke.md"),
		filepath.Join(prepared.Sprint.Path, "flow-state.json"),
	}
	if result.Verdict == SmokePass && !result.DiagnosticOnly {
		workspacePaths = append(workspacePaths, filepath.Join(filepath.Dir(filepath.Dir(prepared.Sprint.Path)), "roadmap.md"))
	}
	workspaceResult, err := s.publisher.Publish(ctx, gitpublish.Request{Root: s.root, Paths: workspacePaths, Message: message, Identity: identity + "/workspace"})
	results = append(results, visiblePublication(workspaceResult)...)
	return results, err
}

func visiblePublication(result gitpublish.Result) []gitpublish.Result {
	if result.Repository == "" && result.Skipped {
		return nil
	}
	return []gitpublish.Result{result}
}

